// Los 4 hubs principales (bola grande) por estructura.
const HUB_IDS = ["avenida-boyacá", "avenida-ciudad-de-cali", "río-bogotá", "cerros-orientales", "manzanas_del_cuidado"];

/* Nodos apagados por la simulación ("¿qué pasaría si se apaga este nodo?").
   Se declara aquí, antes del layout, porque el acomodo de la red ya
   consulta qué está apagado. */
const nodosApagados = new Set();

/* Tipo/categoría apagados desde la leyenda. Igual que nodosApagados, se
   declaran antes del layout: computeDegrees() ya los consulta desde el
   primer cálculo de grados (layoutNetwork() más abajo), y si se declararan
   más adelante en el archivo, esa primera llamada fallaría por acceder a
   la variable antes de su inicialización.
   Las relaciones "indirecta" (por cruce o intersección espacial, la
   evidencia más débil) arrancan apagadas: con las 132 relaciones visibles
   encendidas de una vez la red se veía como una maraña de líneas. Así entra
   solo con las 83 "directa" (respaldo explícito del POT) y el botón de la
   leyenda sigue encendiéndolas si se quieren ver. */
const typeOff = new Set(["indirecta"]), nodeOff = new Set(), catOff = new Set();

/* Radio de cada bola: sale del grado real (cuántas relaciones vigentes
   tiene). Un nodo apagado se encoge a un tamaño fijo. Es la MISMA fórmula
   que usa la simulación de apagado, para que al encender y apagar los
   tamaños vuelvan exactamente a donde estaban. */
function radioPorGrado(d, apagado) {
  return apagado ? 30 : 30 + d * 5.8;   // la fuerza nodal se ve: cada relación suma tamaño
}

/* Radio mínimo para que el nombre no tenga que partirse a la mitad: los
   nombres largos (SERVICIOS EMPRESARIALES, CENTROS DE ABASTECIMIENTO)
   necesitan una bola algo más ancha. Con tope, para no borrar la
   diferencia de tamaño entre un hub y un elemento periférico. */
function radioParaNombre(nombre) {
  const larga = String(nombre || "").split(/[\s\n]+/).reduce((a, p) => Math.max(a, p.length), 1);
  return Math.min(52, larga * 4.4);   // lo justo para que el nombre no se parta, sin borrar la diferencia de tamaño
}

/* Separación entre bolas: ninguna puede tocar a otra. Con resorte, cada
   una tira de vuelta a su sitio del wireframe; sin resorte, solo se
   garantiza que no se toquen. Se usa al construir la red y cada vez que
   la simulación cambia los tamaños. */
function separarNodos(nodes, conResorte, pasadas) {
  const MIN_GAP = 30, SPRING = 0.05;   // aire mínimo entre dos bolas, siempre
  for (let pass = 0; pass < pasadas; pass++) {
    let anyOverlap = false;
    for (let i = 0; i < nodes.length; i++) {
      for (let j = i + 1; j < nodes.length; j++) {
        const a = nodes[i], b = nodes[j];
        let dx = b.x - a.x, dy = b.y - a.y;
        let dist = Math.hypot(dx, dy);
        const minDist = a.collR + b.collR + MIN_GAP;
        if (dist < minDist) {
          anyOverlap = true;
          if (dist < 0.001) { dx = (Math.random() - 0.5) * 2; dy = (Math.random() - 0.5) * 2; dist = Math.hypot(dx, dy); }
          const overlap = (minDist - dist) / 2;
          const ux = dx / dist, uy = dy / dist;
          a.x -= ux * overlap; a.y -= uy * overlap;
          b.x += ux * overlap; b.y += uy * overlap;
        }
      }
    }
    nodes.forEach(n => {
      if (conResorte) {
        n.x += (n._origX - n.x) * SPRING;
        n.y += (n._origY - n.y) * SPRING;
      }
      n.x = Math.max(n.collR + 20, Math.min(CANVAS.w - n.collR - 20, n.x));
      n.y = Math.max(n.collR + 20, Math.min(CANVAS.h - n.collR - 20, n.y));
    });
    if (!conResorte && !anyOverlap) break;
  }
}

function layoutNetwork() {
  const deg = computeDegrees();
  // Cada bola crece con su grado real: los corredores que cruzan media ciudad
  // (AVENIDA BOYACÁ, AVENIDA CIUDAD DE CALI) quedan como los elementos más
  // conectados de la red, y los que casi no se relacionan, pequeños.
  ODS_NODES.forEach(n => {
    n.color = STRUCT_STYLE[n.cat].color;
    n.vx = 0; n.vy = 0; n.fixed = false; n.isMainHub = false;
    const d = deg[n.id] || 0;
    n.r = Math.max(radioPorGrado(d, false), radioParaNombre(n.name));
    n._deg = d;
    n._degBase = d; // fuerza nodal original, sin ningún nodo apagado — sirve para comparar ANTES ↔ DESPUÉS
  });

  const nodes = DISPLAY_NODES;   // solo la red que se dibuja

  /* ---- Reparto parejo, y de varios intentos se queda el más limpio ----
     El trazado no se deja al azar ni a un parámetro elegido a ojo: se prueban
     varias semillas de reparto, y de cada una se cuentan los CRUCES DE LÍNEA
     y las líneas que pasan por encima de un nodo ajeno. Se dibuja la que
     menos deja. Dentro de cada intento, los elementos que se relacionan se
     atraen entre sí (por eso terminan cerca los que están conectados) y
     ninguna bola puede tocar a otra. */
  const cx0 = CANVAS.w / 2, cy0 = CANVAS.h / 2;
  const gradoDe = (n) => deg[n.id] || 0;
  const vecinosDe = new Map(nodes.map((n) => [n.id, []]));
  RAW_EDGES.forEach((e) => {
    if (e.tipo === "vacio" || !relacionVisible(e)) return;
    vecinosDe.get(e.s)?.push(e.t);
    vecinosDe.get(e.t)?.push(e.s);
  });
  const parejas = RAW_EDGES.filter((e) => e.tipo !== "vacio" && relacionVisible(e))
    .map((e) => [nodeById(e.s), nodeById(e.t)]).filter(([a, b]) => a && b);

  function costeTrazado() {
    const seCruzan = (a, b, c, d) => {
      const f = (p1, p2, p3) => (p3.y - p1.y) * (p2.x - p1.x) - (p2.y - p1.y) * (p3.x - p1.x);
      const d1 = f(c, d, a), d2 = f(c, d, b), e1 = f(a, b, c), e2 = f(a, b, d);
      return ((d1 > 0 && d2 < 0) || (d1 < 0 && d2 > 0)) && ((e1 > 0 && e2 < 0) || (e1 < 0 && e2 > 0));
    };
    let cruces = 0;
    for (let i = 0; i < parejas.length; i++) {
      for (let j = i + 1; j < parejas.length; j++) {
        const [a, b] = parejas[i], [c, d] = parejas[j];
        if (a === c || a === d || b === c || b === d) continue;
        if (seCruzan(a, b, c, d)) cruces++;
      }
    }
    let sobreNodos = 0;
    parejas.forEach(([a, b]) => {
      const dx = b.x - a.x, dy = b.y - a.y, L2 = dx * dx + dy * dy;
      if (!L2) return;
      nodes.forEach((n) => {
        if (n === a || n === b) return;
        let t = ((n.x - a.x) * dx + (n.y - a.y) * dy) / L2;
        t = Math.max(0, Math.min(1, t));
        if (Math.hypot(a.x + t * dx - n.x, a.y + t * dy - n.y) < n.r * 0.8) sobreNodos++;
      });
    });
    return cruces + sobreNodos * 2;
  }

  function unIntento(giro, fuerza) {
    const ordenados = [...nodes].sort((a, b) => gradoDe(b) - gradoDe(a));
    const rMax = Math.min(CANVAS.w, CANVAS.h) / 2 - 130;
    ordenados.forEach((n, i) => {
      const t = (i + 0.5) / ordenados.length;
      const rad = rMax * Math.sqrt(t);
      const ang = giro + i * 2.399963;
      n.collR = n.r;
      n.x = cx0 + Math.cos(ang) * rad * (CANVAS.w / CANVAS.h);
      n.y = cy0 + Math.sin(ang) * rad;
    });
    const dentro = () => nodes.forEach((n) => {
      n.x = Math.max(n.collR + 40, Math.min(CANVAS.w - n.collR - 40, n.x));
      n.y = Math.max(n.collR + 40, Math.min(CANVAS.h - n.collR - 40, n.y));
    });
    dentro();
    separarNodos(nodes, false, 200);
    for (let pass = 0; pass < 190; pass++) {
      nodes.forEach((n) => {
        const vs = vecinosDe.get(n.id) || [];
        if (!vs.length) return;
        let vx = 0, vy = 0, cuenta = 0;
        vs.forEach((id) => { const v = nodeById(id); if (v && DISPLAY_NODE_IDS.has(id)) { vx += v.x; vy += v.y; cuenta++; } });
        if (!cuenta) return;
        n.x += (vx / cuenta - n.x) * fuerza;
        n.y += (vy / cuenta - n.y) * fuerza;
      });
      nodes.forEach((n) => {
        const dx = n.x - cx0, dy = n.y - cy0;
        const d = Math.hypot(dx, dy) || 1;
        const objetivo = rMax * 0.72;
        if (d < objetivo) { const f = (objetivo - d) * 0.004; n.x += (dx / d) * f; n.y += (dy / d) * f; }
      });
      dentro();
      separarNodos(nodes, false, 1);
    }
    separarNodos(nodes, false, 300);
    return costeTrazado();
  }

  let mejor = null;
  const GIROS = [0, 0.5, 1.0, 1.6, 2.2, 2.8, 3.4, 4.0];
  const FUERZAS = [0.13, 0.17, 0.21];
  GIROS.forEach((giro) => FUERZAS.forEach((fuerza) => {
    const coste = unIntento(giro, fuerza);
    if (!mejor || coste < mejor.coste) {
      mejor = { coste, pos: nodes.map((n) => ({ x: n.x, y: n.y })) };
    }
  }));
  nodes.forEach((n, i) => { n.x = mejor.pos[i].x; n.y = mejor.pos[i].y; });
  separarNodos(nodes, false, 200);
  // el "sitio de casa" es la posición final del arranque: así, al volver a
  // encender un nodo, la red regresa exactamente al dibujo inicial
  nodes.forEach(n => {
    n.isMainHub = (HUB_IDS.indexOf(n.id) !== -1);
    n._origX = n.x; n._origY = n.y;
  });

  nodes.forEach(n => { n.homeX = n.x; n.homeY = n.y; });

  // Centrar toda la red dentro del recuadro de visualización: se calcula
  // el centro real del conjunto de bolas y se traslada todo para que
  // coincida con el centro del lienzo, sin importar cómo haya quedado
  // repartido el layout.
  const xsFinal = nodes.map(n => n.x), ysFinal = nodes.map(n => n.y);
  const centroRealX = (Math.min(...xsFinal) + Math.max(...xsFinal)) / 2;
  const centroRealY = (Math.min(...ysFinal) + Math.max(...ysFinal)) / 2;
  const despX = CANVAS.w / 2 - centroRealX, despY = CANVAS.h / 2 - centroRealY;
  nodes.forEach(n => {
    n.x += despX; n.y += despY;
    n._origX += despX; n._origY += despY;
    n.homeX += despX; n.homeY += despY;
  });
}
layoutNetwork();

RAW_EDGES.forEach(edge => {
  const s = nodeById(edge.s), t = nodeById(edge.t);
  if (!s || !t) { console.warn("Arista con nodo inexistente:", edge.s, edge.t); return; }
  edge.restLength = Math.hypot(t.x - s.x, t.y - s.y);
});

// Vecinos directos de cada nodo (solo por relaciones que sí se dibujan):
// al arrastrar una bola, las que están conectadas a ella se dejan llevar.
const VECINOS_DIRECTOS = new Map(DISPLAY_NODES.map((n) => [n.id, []]));
RAW_EDGES.forEach((e) => {
  if (e.tipo === "vacio" || !relacionVisible(e)) return;
  VECINOS_DIRECTOS.get(e.s)?.push(e.t);
  VECINOS_DIRECTOS.get(e.t)?.push(e.s);
});

/* No puede haber una línea recta encima de otra: con el reparto final ya
   fijo, cualquier relación cuyo trazo recto pase muy cerca de una tercera
   bola (por ejemplo, dos vecinos casi en línea con ella) queda marcada
   para dibujarse con una leve curva — así nunca se confunde con las
   líneas de esa tercera bola, sin tener que tocar los datos cada vez que
   el reparto cambia. */
(function marcarLineasQueDebenCurvarse() {
  const visibles = RAW_EDGES.filter(e => e.tipo !== "vacio" && relacionVisible(e));
  visibles.forEach(edge => {
    const a = nodeById(edge.s), c = nodeById(edge.t);
    if (!a || !c) return;
    const dx = c.x - a.x, dy = c.y - a.y, L2 = dx * dx + dy * dy;
    if (!L2) return;
    const pasaCerca = DISPLAY_NODES.some((b) => {
      if (b.id === a.id || b.id === c.id) return false;
      let t = ((b.x - a.x) * dx + (b.y - a.y) * dy) / L2;
      if (t < 0.12 || t > 0.88) return false;   // solo cuenta si b queda BIEN adentro del tramo, no cerca de una punta
      const projX = a.x + t * dx, projY = a.y + t * dy;
      return Math.hypot(projX - b.x, projY - b.y) < b.r * 0.9;
    });
    if (pasaCerca) edge._curvar = true;
  });
})();

/* ==========================================================
   La red es ESTÁTICA: sin zoom ni pan. El lienzo SVG se ajusta
   siempre por completo al contenedor mediante el viewBox fijo.
   ========================================================== */

/* -------- defs -------- */
function buildDefs(svg) {
  const defs = document.createElementNS(SVG_NS, "defs");
  const uniqueColors = [...new Set(ODS_NODES.map(n => n.color))];
  uniqueColors.forEach(color => {
    const filter = document.createElementNS(SVG_NS, "filter");
    filter.setAttribute("id", "glow-" + color.replace("#", ""));
    filter.setAttribute("x", "-60%"); filter.setAttribute("y", "-60%");
    filter.setAttribute("width", "220%"); filter.setAttribute("height", "220%");
    const blur = document.createElementNS(SVG_NS, "feGaussianBlur");
    blur.setAttribute("stdDeviation", "3"); blur.setAttribute("result", "blur");
    const merge = document.createElementNS(SVG_NS, "feMerge");
    ["blur", "blur", "SourceGraphic"].forEach(ref => {
      const m = document.createElementNS(SVG_NS, "feMergeNode"); m.setAttribute("in", ref); merge.appendChild(m);
    });
    filter.appendChild(blur); filter.appendChild(merge);
    defs.appendChild(filter);
  });
  // marcadores de flecha: solo 2 colores en toda la red — Soporte (naranja) y Resiliencia (azul).
  // "vacío" NO usa un tercer color: hereda el color de su propia dimensión Soporte/Resiliencia,
  // y se distingue únicamente por el estilo de línea (punteado disperso, ver drawEdges).
  const arrowColors = { "Soporte": RELACION_STYLE.Soporte.color, "Resiliencia": RELACION_STYLE.Resiliencia.color };
  Object.entries(arrowColors).forEach(([key, color]) => {
    const marker = document.createElementNS(SVG_NS, "marker");
    marker.setAttribute("id", "arrow-" + key);
    marker.setAttribute("viewBox", "0 0 10 10");
    marker.setAttribute("refX", "8"); marker.setAttribute("refY", "5");
    marker.setAttribute("markerWidth", "6"); marker.setAttribute("markerHeight", "6");
    marker.setAttribute("orient", "auto-start-reverse");
    const path = document.createElementNS(SVG_NS, "path");
    path.setAttribute("d", "M0,0 L10,5 L0,10 z");
    path.setAttribute("fill", color);
    marker.appendChild(path);
    defs.appendChild(marker);
  });
  svg.appendChild(defs);
}

/* ==========================================================
   FONDO DE MAPA — silueta ESQUEMÁTICA de Bogotá D.C. (perímetro urbano +
   cerros orientales), trazada a mano sobre puntos de referencia conocidos
   de la forma general de la ciudad (alargada norte-sur, borde oriental
   recto por los Cerros, borde occidental más irregular por el río Bogotá
   y los humedales). Es una aproximación decorativa, NO cartografía oficial
   georreferenciada (no reemplaza IDECA/SDP) — se indica así en el title
   del ícono de escala, para no reclamar una precisión que no tenemos.
   La textura de "terreno" se genera con feTurbulence (ruido procedural),
   igual de forma al look de foto-satelital oscura de la referencia.
   ========================================================== */
function buildMapBackground(svg) {
  const g = document.createElementNS(SVG_NS, "g");
  g.setAttribute("class", "map-bg-layer");

  const cx = CANVAS.w / 2, cy = CANVAS.h / 2;
  // silueta esquemática: alargada N-S, borde oriental (derecha) casi recto,
  // borde occidental más irregular. Puntos en sentido horario desde el norte.
  const shapePts = [
    [0.30,0.02],[0.45,0.03],[0.55,0.05],[0.62,0.10],[0.66,0.16],
    [0.70,0.20],[0.72,0.27],[0.70,0.33],[0.74,0.38],[0.71,0.44],
    [0.75,0.50],[0.72,0.56],[0.76,0.62],[0.73,0.68],[0.70,0.74],
    [0.66,0.80],[0.60,0.86],[0.52,0.91],[0.44,0.95],[0.36,0.98],
    [0.28,0.96],[0.22,0.90],[0.20,0.82],[0.15,0.76],[0.18,0.68],
    [0.12,0.62],[0.16,0.55],[0.10,0.48],[0.14,0.41],[0.09,0.34],
    [0.13,0.27],[0.10,0.20],[0.15,0.13],[0.20,0.07],[0.26,0.03],
  ];
  const pts = shapePts.map(([px, py]) => ({ x: px * CANVAS.w, y: py * CANVAS.h }));

  function smoothClosedPath(points) {
    let d = "";
    const n = points.length;
    const mid = (a, b) => ({ x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 });
    const start = mid(points[n - 1], points[0]);
    d += `M${start.x},${start.y} `;
    for (let i = 0; i < n; i++) {
      const p = points[i], next = points[(i + 1) % n];
      const m = mid(p, next);
      d += `Q${p.x},${p.y} ${m.x},${m.y} `;
    }
    d += "Z";
    return d;
  }

  const blobPath = smoothClosedPath(pts);
  const blobId = "mapBlobShape";

  const defs = document.createElementNS(SVG_NS, "defs");
  const clip = document.createElementNS(SVG_NS, "clipPath");
  clip.setAttribute("id", blobId + "-clip");
  const clipPath = document.createElementNS(SVG_NS, "path");
  clipPath.setAttribute("d", blobPath);
  clip.appendChild(clipPath);
  defs.appendChild(clip);

  // textura de "terreno" procedural (ruido) — imita el look foto-satelital
  // oscuro y rugoso de la referencia, sin pretender ser datos reales de elevación.
  const filter = document.createElementNS(SVG_NS, "filter");
  filter.setAttribute("id", "terrainNoise");
  filter.setAttribute("x", "-5%"); filter.setAttribute("y", "-5%");
  filter.setAttribute("width", "110%"); filter.setAttribute("height", "110%");
  const turb = document.createElementNS(SVG_NS, "feTurbulence");
  turb.setAttribute("type", "fractalNoise");
  turb.setAttribute("baseFrequency", "0.012 0.018");
  turb.setAttribute("numOctaves", "4");
  turb.setAttribute("seed", "7");
  turb.setAttribute("result", "noise");
  const colorMatrix = document.createElementNS(SVG_NS, "feColorMatrix");
  colorMatrix.setAttribute("in", "noise");
  colorMatrix.setAttribute("type", "matrix");
  colorMatrix.setAttribute("values", "0 0 0 0 0.08  0 0 0 0 0.10  0 0 0 0 0.11  0 0 0 0.55 0");
  filter.appendChild(turb); filter.appendChild(colorMatrix);
  defs.appendChild(filter);
  g.appendChild(defs);

  // relleno base oscuro de la silueta
  const fill = document.createElementNS(SVG_NS, "path");
  fill.setAttribute("d", blobPath);
  fill.setAttribute("fill", "#111111");
  g.appendChild(fill);

  // textura de terreno, recortada a la silueta
  const noiseRect = document.createElementNS(SVG_NS, "rect");
  noiseRect.setAttribute("x", "0"); noiseRect.setAttribute("y", "0");
  noiseRect.setAttribute("width", CANVAS.w); noiseRect.setAttribute("height", CANVAS.h);
  noiseRect.setAttribute("filter", "url(#terrainNoise)");
  noiseRect.setAttribute("clip-path", `url(#${blobId}-clip)`);
  g.appendChild(noiseRect);

  // viñeta radial suave (oscurece bordes, ilumina centro — como la referencia)
  const vignette = document.createElementNS(SVG_NS, "radialGradient");
  vignette.setAttribute("id", "mapVignette");
  vignette.setAttribute("cx", "50%"); vignette.setAttribute("cy", "42%"); vignette.setAttribute("r", "65%");
  const stop1 = document.createElementNS(SVG_NS, "stop");
  stop1.setAttribute("offset", "0%"); stop1.setAttribute("stop-color", "#1a1a1a"); stop1.setAttribute("stop-opacity", "0.3");
  const stop2 = document.createElementNS(SVG_NS, "stop");
  stop2.setAttribute("offset", "100%"); stop2.setAttribute("stop-color", "#000000"); stop2.setAttribute("stop-opacity", "0.55");
  vignette.appendChild(stop1); vignette.appendChild(stop2);
  defs.appendChild(vignette);
  const vignetteRect = document.createElementNS(SVG_NS, "rect");
  vignetteRect.setAttribute("x", "0"); vignetteRect.setAttribute("y", "0");
  vignetteRect.setAttribute("width", CANVAS.w); vignetteRect.setAttribute("height", CANVAS.h);
  vignetteRect.setAttribute("fill", "url(#mapVignette)");
  vignetteRect.setAttribute("clip-path", `url(#${blobId}-clip)`);
  g.appendChild(vignetteRect);

  // borde de la silueta
  const outline = document.createElementNS(SVG_NS, "path");
  outline.setAttribute("d", blobPath);
  outline.setAttribute("fill", "none");
  outline.setAttribute("stroke", "rgba(200,200,200,0.22)");
  outline.setAttribute("stroke-width", "1.5");
  g.appendChild(outline);

  svg.appendChild(g);
}

/* ==========================================================
   MESH AMBIENTAL — puntos y líneas finas de fondo, puramente decorativos
   (NO son los 40 componentes reales, que se dibujan aparte en drawNodes).
   Dan la densidad visual de "mesh de ciudad" de la referencia sin mezclar
   datos reales con relleno visual. Coordenadas fijas (no aleatorias) para
   que el resultado sea reproducible en cada carga.
   ========================================================== */
function buildAmbientMesh(svg) {
  const g = document.createElementNS(SVG_NS, "g");
  g.setAttribute("class", "ambient-mesh-layer");
  g.setAttribute("opacity", "0.5");

  // grilla fija con offset determinístico (sin Math.random) para look orgánico
  const seedPts = [];
  const cols = 14, rows = 16;
  for (let i = 0; i < cols; i++) {
    for (let j = 0; j < rows; j++) {
      const baseX = (i + 0.5) / cols * CANVAS.w;
      const baseY = (j + 0.5) / rows * CANVAS.h;
      const jitterX = (((i * 37 + j * 19) % 23) - 11) * 6;
      const jitterY = (((i * 17 + j * 41) % 29) - 14) * 6;
      seedPts.push({ x: baseX + jitterX, y: baseY + jitterY, idx: i * rows + j });
    }
  }
  // colores ambientales: ciclan entre los 4 colores de estructura para dar
  // la sensación de "mesh multicolor" de la referencia
  const palette = ["#5cd6d1", "#ef9f54", "#fac47b", "#fb8d84"];

  // líneas finas entre puntos cercanos (umbral de distancia)
  const THRESH = 230;
  for (let i = 0; i < seedPts.length; i++) {
    for (let j = i + 1; j < seedPts.length; j++) {
      const a = seedPts[i], b = seedPts[j];
      const d = Math.hypot(a.x - b.x, a.y - b.y);
      if (d < THRESH && (a.idx + b.idx) % 3 !== 0) {
        const line = document.createElementNS(SVG_NS, "line");
        line.setAttribute("x1", a.x); line.setAttribute("y1", a.y);
        line.setAttribute("x2", b.x); line.setAttribute("y2", b.y);
        line.setAttribute("stroke", palette[a.idx % 4]);
        line.setAttribute("stroke-width", "0.6");
        line.setAttribute("opacity", "0.22");
        g.appendChild(line);
      }
    }
  }
  seedPts.forEach(p => {
    const dot = document.createElementNS(SVG_NS, "circle");
    dot.setAttribute("cx", p.x); dot.setAttribute("cy", p.y);
    dot.setAttribute("r", (p.idx % 5 === 0) ? 3.2 : 1.8);
    dot.setAttribute("fill", palette[p.idx % 4]);
    dot.setAttribute("opacity", (p.idx % 5 === 0) ? "0.55" : "0.4");
    g.appendChild(dot);
  });

  svg.appendChild(g);
}

// Color del trazo: SOLO 2 colores en toda la red — Soporte (naranja) y Resiliencia (azul).
// El estilo de línea (sólida+flecha / punteada / punteada dispersa) es lo que distingue
// directa / indirecta / vacío — nunca el color.
function edgeColor(edge) {
  return (edge.relacion && RELACION_STYLE[edge.relacion]) ? RELACION_STYLE[edge.relacion].color : RELACION_STYLE.Soporte.color;
}
function arrowMarkerId(edge) {
  if (edge.relacion) return "arrow-" + edge.relacion;
  return null;
}

function edgePathData(edge, s, t) {
  const dx = t.x - s.x, dy = t.y - s.y;
  const dist = Math.sqrt(dx * dx + dy * dy) || 1;
  const ux = dx / dist, uy = dy / dist;
  const startPad = (s.collR || s.r) + 2, endPad = (t.collR || t.r) + 6;
  const x1 = s.x + ux * startPad, y1 = s.y + uy * startPad;
  const x2 = t.x - ux * endPad, y2 = t.y - uy * endPad;
  if (!edge._curvar) return `M${x1},${y1} L${x2},${y2}`;
  // Se separa con una curva suave (no una línea recta) para que nunca se
  // confunda con las líneas de la bola que queda de paso. El lado hacia el
  // que se dobla es siempre el mismo para este par (no cambia si se
  // reconstruye la red), para que la curva no "salte" de un lado a otro.
  const midX = (x1 + x2) / 2, midY = (y1 + y2) / 2;
  const nx = -uy, ny = ux;   // perpendicular a la línea
  const lado = edge.s < edge.t ? 1 : -1;
  const arco = Math.min(46, Math.max(16, dist * 0.14)) * lado;
  const ctrlX = midX + nx * arco, ctrlY = midY + ny * arco;
  return `M${x1},${y1} Q${ctrlX},${ctrlY} ${x2},${y2}`;
}

function drawEdges(svg) {
  const g = document.createElementNS(SVG_NS, "g");
  g.setAttribute("class", "edges-layer");
  // Las líneas aparecen DESPUÉS de que las bolas ya se están formando (no
  // de primeras, que se ve raro) — cada una con su propio pequeño retraso.
  const edgeBaseDelay = DISPLAY_NODES.length * 38 + 300;   // las líneas arrancan cuando ya están todas las bolas
  // Las líneas también aparecen en el orden en que se armó la red: primero
  // las del elemento más conectado, después las de sus vecinos.
  const ordenNodo = new Map();
  ordenDeAparicion().forEach((idx, orden) => { ordenNodo.set(DISPLAY_NODES[idx]?.id, orden); });
  const prioridad = (e) => Math.max(ordenNodo.get(e.s) ?? 999, ordenNodo.get(e.t) ?? 999);
  const ordenAristas = new Map();
  RAW_EDGES.map((e, i) => [i, e]).filter(([, e]) => relacionVisible(e))
    .sort((a, b) => prioridad(a[1]) - prioridad(b[1]))
    .forEach(([i], orden) => ordenAristas.set(i, orden));
  let edgeOrderIndex = 0;
  RAW_EDGES.forEach((edge, i) => {
    if (!relacionVisible(edge)) return;
    // Las relaciones "vacío" (ausencias documentadas entre estructuras) ya NO
    // se dibujan en la red visual — quedan solo como hallazgo en la tabla y en
    // las tarjetas de "hallazgos clave", para que la red se lea limpia con
    // únicamente relaciones reales (directa/indirecta).
    if (edge.tipo === "vacio") return;
    const s = nodeById(edge.s), t = nodeById(edge.t);
    if (!s || !t) return;
    const color = edgeColor(edge);
    const d = edgePathData(edge, s, t);

    const group = document.createElementNS(SVG_NS, "g");
    group.setAttribute("class", "edge-group edge-" + edge.tipo + " edge-group-reveal");
    group.setAttribute("data-index", i);
    group.setAttribute("data-type", edge.tipo);
    group.setAttribute("data-cat", edge.cat);
    group.setAttribute("data-source", edge.s);
    group.setAttribute("data-target", edge.t);
    group.style.setProperty("--edge-color", color);
    group.style.setProperty("--reveal-delay", (edgeBaseDelay + (ordenAristas.get(i) ?? edgeOrderIndex) * 18) + "ms");
    edgeOrderIndex++;

    const hit = document.createElementNS(SVG_NS, "path");
    hit.setAttribute("d", d); hit.setAttribute("class", "ods-edge edge-hit");
    hit.setAttribute("stroke-width", "30");   // zona de clic ancha: la línea se agarra fácil, también con el dedo

    // Las relaciones que tocan una vía (Avenida Boyacá, Av. Ciudad de Cali,
    // cualquier avenida/calle/carrera) se dibujan más delgadas y punteadas
    // que el resto: una vía cruza media ciudad y concentra tantas relaciones
    // que sus líneas gruesas y sólidas ahogaban el resto de la red.
    const tocaVia = CONTENCION.red_vial.test(edge.s) || CONTENCION.red_vial.test(edge.t);
    const visual = document.createElementNS(SVG_NS, "path");
    visual.setAttribute("d", d);
    visual.setAttribute("class", "ods-edge edge-visual");
    visual.setAttribute("stroke", color);
    visual.setAttribute("stroke-width", edge.tipo === "vacio" ? 2.6 : tocaVia ? 0.6 : edge.tipo === "directa" ? 1.2 : 0.7);
    if (edge.tipo !== "directa" || tocaVia) visual.setAttribute("stroke-dasharray", edge.tipo === "vacio" ? "2,7" : "5,4");
    const markerId = arrowMarkerId(edge);
    if (markerId) visual.setAttribute("marker-end", `url(#${markerId})`);
    visual.setAttribute("opacity", edge.tipo === "indirecta" ? "0.55" : edge.tipo === "vacio" ? "0.8" : "0.95");

    group.appendChild(visual); group.appendChild(hit);
    group.addEventListener("click", (ev) => { ev.stopPropagation(); showEdgeInfo(i); });
    g.appendChild(group);
    edge._el = { visual, hit, d };
  });
  svg.appendChild(g);
}

// Estilo "referencia": solo los 4 hubs principales llevan ícono + etiqueta de texto
// al lado (igual que "Humedales", "Actuaciones estratégicas", etc. en la imagen).
// El resto de los 36 componentes reales se muestran como puntos de color sólido,
// sin texto dentro — igual que los puntitos del mesh de fondo de la referencia —
// para no saturar la vista; su ficha completa sigue disponible al hacer clic.
// TODOS los nodos (hub y satélite) llevan círculo con anillo + ícono + nombre
// dentro — el tamaño (radio, ícono, texto) escala con el grado real, así que
// los hubs se leen mucho más grandes que la periferia sin dejar de mostrar
// la etiqueta de cada componente.
/* Orden en que se arma la red: se arranca del elemento más conectado y se
   avanza a sus vecinos, y de ahí a los vecinos de esos (recorrido por
   anchura). Así cada bola que aparece se engancha con algo que ya está en
   pantalla, y la red se ve armarse en vez de salir a pedazos sueltos. */
function ordenDeAparicion() {
  const grado = computeDegrees();
  const vecinos = new Map(DISPLAY_NODES.map((n) => [n.id, []]));
  RAW_EDGES.forEach((e) => {
    if (e.tipo === "vacio" || !relacionVisible(e)) return;
    vecinos.get(e.s)?.push(e.t);
    vecinos.get(e.t)?.push(e.s);
  });
  const g = (id) => grado[id] || 0;
  const porGrado = [...DISPLAY_NODES].sort((a, b) => g(b.id) - g(a.id));
  const indice = new Map(DISPLAY_NODES.map((n, i) => [n.id, i]));
  const visto = new Set(), orden = [];
  porGrado.forEach((raiz) => {
    if (visto.has(raiz.id)) return;
    const cola = [raiz.id]; visto.add(raiz.id);
    while (cola.length) {
      const id = cola.shift();
      orden.push(indice.get(id));
      (vecinos.get(id) || [])
        .sort((x, y) => g(y) - g(x))
        .forEach((v) => { if (!visto.has(v) && indice.has(v)) { visto.add(v); cola.push(v); } });
    }
  });
  DISPLAY_NODES.forEach((n, i) => { if (!orden.includes(i)) orden.push(i); });
  return orden;
}

function drawNodes(svg) {
  const g = document.createElementNS(SVG_NS, "g");
  g.setAttribute("class", "nodes-layer");
  // Orden de aparición aleatorio (no siempre el mismo), para que la red
  // se sienta viva desde el primer instante en vez de aparecer de golpe.
  const revealOrder = ordenDeAparicion();
  for (let i = -1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [revealOrder[i], revealOrder[j]] = [revealOrder[j], revealOrder[i]];
  }
  const revealDelay = {};
  revealOrder.forEach((nodeIndex, order) => { revealDelay[nodeIndex] = order * 38; });
  DISPLAY_NODES.forEach((node, index) => {
    const group = document.createElementNS(SVG_NS, "g");
    group.setAttribute("class", "ods-node ods-node-" + node.cat + (node.isMainHub ? " ods-hub" : " ods-satellite") + " ods-node-reveal");
    group.setAttribute("data-id", node.id);
    group.setAttribute("data-cat", node.cat);
    group.style.setProperty("--reveal-delay", revealDelay[index] + "ms");

    const circle = document.createElementNS(SVG_NS, "circle");
    circle.setAttribute("class", "node-ring" + (node.isMainHub ? " node-ring-hub" : ""));
    circle.setAttribute("cx", node.x); circle.setAttribute("cy", node.y); circle.setAttribute("r", node.r);
    circle.setAttribute("fill", "#0a0a0a");
    circle.setAttribute("stroke", node.color);
    circle.setAttribute("stroke-width", node.isMainHub ? 1.4 : 0.9);
    circle.setAttribute("filter", "url(#glow-" + node.color.replace("#", "") + ")");

    const fo = document.createElementNS(SVG_NS, "foreignObject");
    const ancho = anchoRotulo(node), alto = node.r * 2.0;
    fo.setAttribute("x", node.x - ancho / 2); fo.setAttribute("y", node.y - alto / 2);
    fo.setAttribute("width", ancho); fo.setAttribute("height", alto);
    // el rótulo no recibe clics: los recibe la bola que está debajo
    fo.setAttribute("pointer-events", "none");

    const wrapper = document.createElementNS(XHTML_NS, "div");
    wrapper.setAttribute("style", "width:100%;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;pointer-events:none;padding:2px;overflow:hidden;");

    const iconEl = document.createElementNS(XHTML_NS, "i");
    iconEl.setAttribute("class", "fa-solid " + node.icon);
    iconEl.setAttribute("style", `color:${node.color}; font-size:${Math.max(node.r * 0.20, 10)}px;`);

    const nameEl = document.createElementNS(XHTML_NS, "div");
    nameEl.setAttribute("style", `font-size:${fuenteQueCabe(node)}px; padding:0 1px; font-weight:700; color:#f2f3f6; line-height:1.15; white-space:pre-line; overflow-wrap:normal; text-align:center; font-family:'Inter',sans-serif;`);
    nameEl.textContent = node.name;

    wrapper.appendChild(iconEl); wrapper.appendChild(nameEl);
    fo.appendChild(wrapper);
    group.appendChild(circle); group.appendChild(fo);
    attachNodeClickHandler(group, node.id);
    attachNodeDragHandler(group, node);
    g.appendChild(group);
    node._el = { group, circle, fo };
  });
  svg.appendChild(g);
}

/* -------- física de interacción (arrastre) -------- */
const PHYSICS = {
  spring: 0.010,      // spring: barely holds edges
  linkDistance: 3,    // links 3x longer
  anchor: 0.002,      // anchor: almost zero (repulsion dominates)
  damping: 0.70,      // damping slightly increased for stability
  minVel: 0.005,      // minimum velocity
  repulsion: 10,      // ULTRA EXTREME (800x in inverse square repulsion)
  collisionPadding: 1.5 // collision radius + 25px mandatory spacing
};

function updatePositions() {
  ODS_NODES.forEach(n => {
    if (!n._el) return;
    n._el.circle.setAttribute("cx", n.x); n._el.circle.setAttribute("cy", n.y);
    const ancho = anchoRotulo(n), alto = n.r * 2.0;
    n._el.fo.setAttribute("x", n.x - ancho / 2); n._el.fo.setAttribute("y", n.y - alto / 2);
  });
  RAW_EDGES.forEach(edge => {
    if (!edge._el) return;
    const s = nodeById(edge.s), t = nodeById(edge.t);
    if (!s || !t) return;
    const d = edgePathData(edge, s, t);
    edge._el.visual.setAttribute("d", d); edge._el.hit.setAttribute("d", d);
  });
}

/* ==========================================================
   FUERZA NODAL — la pregunta del módulo es "¿qué pasaría si se
   apaga este nodo?". Al apagar un nodo, sus aristas dejan de
   contar en el grado (computeDegrees) de todos los demás, y cada
   bola se redimensiona en vivo según su NUEVO grado real: los
   nodos que dependían del apagado "pierden fuerza" (se encogen),
   los demás la conservan. El nodo apagado se atenúa (gris) y sus
   aristas quedan tenues, pero siguen visibles como registro del
   ANTES.
   ========================================================== */

// Reaplica r/tamaño/posición a un solo nodo ya dibujado en el DOM,
// sin reconstruir toda la red (usado al recalcular fuerza nodal).
/* Tamaño de letra que cabe dentro de la bola: se mide la palabra más larga
   del nombre y se baja la letra hasta que quepa en el ancho útil del círculo.
   Antes los nombres largos (CENTROS DE ABASTECIMIENTO, SERVICIOS
   EMPRESARIALES) se salían por los lados. */
function palabraMasLarga(nombre) {
  return String(nombre || "").split(/[\s\n]+/).reduce((a, w) => Math.max(a, w.length), 1);
}

function fuenteQueCabe(node) {
  // Un poco más chica que antes: en las bolas pequeñas (la mayoría, ahora
  // que el tamaño solo cuenta las líneas visibles) la letra + el ícono ya
  // no se salían del anillo.
  return Math.max(10, Math.min(node.r * 0.24, 22));
}

/* Ancho del rótulo. Cuando el nombre es una palabra larga (CHIGUASUQUE,
   CAPELLANÍA, CIRCUNVALAR) no se parte a la mitad: el rótulo se ensancha un
   poco más que la bola y el texto sale entero sobre el fondo. El tope evita
   que dos rótulos vecinos se toquen. */
function anchoRotulo(node) {
  const necesario = palabraMasLarga(node.name) * fuenteQueCabe(node) * 0.70 + 10;
  return Math.max(node.r * 1.8, Math.min(necesario, node.r * 3.1));
}

function resizeNodeVisual(n) {
  if (!n._el) return;
  const { circle, fo } = n._el;
  const apagado = nodosApagados.has(n.id);
  circle.setAttribute("r", n.r);
  const ancho = anchoRotulo(n), alto = n.r * 2.0;
  fo.setAttribute("x", n.x - ancho / 2); fo.setAttribute("y", n.y - alto / 2);
  fo.setAttribute("width", ancho); fo.setAttribute("height", alto);
  const iconEl = fo.querySelector("i");
  if (iconEl) iconEl.style.fontSize = Math.max(n.r * 0.20, 10) + "px";
  const nameEl = fo.querySelector("div");
  if (nameEl) {
    // En un nodo apagado la bola es demasiado chica para su nombre: se deja
    // solo el ícono, y el nombre vuelve al encenderlo.
    nameEl.style.display = apagado ? "none" : "";
    nameEl.style.fontSize = fuenteQueCabe(n) + "px";
  }
}

// Recalcula el grado real (fuerza nodal) de TODA la red teniendo en cuenta
// los nodos actualmente apagados, y redibuja cada bola con su nuevo tamaño.
function aplicarFuerzaNodal(reacomodar) {
  const deg = computeDegrees(nodosApagados);
  DISPLAY_NODES.forEach(n => {
    const apagado = nodosApagados.has(n.id);
    const d = deg[n.id] || 0;
    n._deg = d;
    n.r = apagado ? radioPorGrado(d, true) : Math.max(radioPorGrado(d, false), radioParaNombre(n.name));
    n.collR = n.r;
    if (n._el) {
      n._el.group.classList.toggle("node-apagado", apagado);
      // desaparece del dibujo: no queda ni el fantasma
      n._el.group.style.display = apagado ? "none" : "";
    }
  });
  document.querySelectorAll(".edge-group").forEach(el => {
    const s = el.dataset.source, t = el.dataset.target;
    const muerta = nodosApagados.has(s) || nodosApagados.has(t);
    el.classList.toggle("edge-apagada", muerta);
    el.style.display = muerta ? "none" : "";
  });
  if (reacomodar === false) {
    DISPLAY_NODES.forEach(resizeNodeVisual);
    updatePositions();
  } else {
    reacomodarRed();
  }
  actualizarInfoSimulacion();
  if (!document.getElementById("m2Conclusiones")?.hidden) abrirConclusionesRed();
}

/* La red se reacomoda de verdad: con los nuevos tamaños se vuelven a
   separar las bolas (partiendo del wireframe, para que la organización
   general no se pierda) y se anima cada nodo y cada arista hasta su nueva
   posición, en vez de saltar. */
/* Reorganización por hubs. La red de arranque es el wireframe del equipo y
   se queda tal cual mientras nada esté apagado: la fuerza de abajo vale
   cero si ningún nodo perdió relaciones. Al apagar un nodo, los que
   dependían de él —y solo ellos— se sueltan de su sitio y se agrupan
   alrededor de las relaciones que les quedan, en proporción a lo que
   perdieron: un elemento que perdía su única relación se mueve mucho; uno
   que perdía una de seis, casi nada. */
function relajarRed(nodes) {
  const deg = computeDegrees(nodosApagados);
  const activo = (id) => !nodosApagados.has(id);
  const vecinos = new Map(nodes.map(n => [n.id, []]));
  RAW_EDGES.forEach(e => {
    if (e.tipo === "vacio") return;
    if (!relacionVisible(e)) return;
    if (!activo(e.s) || !activo(e.t)) return;
    vecinos.get(e.s).push(e.t); vecinos.get(e.t).push(e.s);
  });
  // cuánto perdió cada nodo respecto de su grado original (0 = nada)
  const perdida = new Map();
  nodes.forEach(n => {
    const base = n._degBase || 0, ahora = deg[n.id] || 0;
    perdida.set(n.id, base > 0 && activo(n.id) ? Math.max(0, (base - ahora) / base) : 0);
  });
  // Sin nada apagado, cada bola vuelve exactamente a su sitio de arranque
  // (con 60 pasadas se quedaba a medio camino).
  if (![...perdida.values()].some(v => v > 0)) { separarNodos(nodes, true, 240); return; }

  const K_VECINOS = 0.09, K_CASA = 0.05;
  for (let pass = 0; pass < 260; pass++) {
    nodes.forEach(n => {
      const p = perdida.get(n.id);
      if (!p) return;
      const vs = vecinos.get(n.id);
      if (!vs.length) return;                 // se quedó sin relaciones: se queda en su sitio
      let cx = 0, cy = 0;
      vs.forEach(id => { const v = nodeById(id); cx += v.x; cy += v.y; });
      cx /= vs.length; cy /= vs.length;
      n.x += (cx - n.x) * K_VECINOS * p;
      n.y += (cy - n.y) * K_VECINOS * p;
    });
    nodes.forEach(n => {
      n.x += (n._origX - n.x) * K_CASA;
      n.y += (n._origY - n.y) * K_CASA;
    });
    separarNodos(nodes, false, 1);
  }
}

let animacionRed = null;
function reacomodarRed() {
  const nodes = DISPLAY_NODES;
  const desde = nodes.map(n => ({ x: n.x, y: n.y, r: parseFloat(n._el?.circle.getAttribute("r")) || n.r }));
  nodes.forEach(n => { n.x = n._origX; n.y = n._origY; });
  relajarRed(nodes);
  separarNodos(nodes, false, 150);
  const hasta = nodes.map(n => ({ x: n.x, y: n.y, r: n.r }));

  if (animacionRed) cancelAnimationFrame(animacionRed);
  const t0 = performance.now(), DUR = 620;
  const suave = (t) => t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;   // easeInOutCubic
  function paso(ahora) {
    const k = suave(Math.min(1, (ahora - t0) / DUR));
    nodes.forEach((n, i) => {
      n.x = desde[i].x + (hasta[i].x - desde[i].x) * k;
      n.y = desde[i].y + (hasta[i].y - desde[i].y) * k;
      n.r = desde[i].r + (hasta[i].r - desde[i].r) * k;
      resizeNodeVisual(n);
    });
    updatePositions();
    if (k < 1) animacionRed = requestAnimationFrame(paso);
    else {
      animacionRed = null;
      nodes.forEach((n, i) => { n.x = hasta[i].x; n.y = hasta[i].y; n.r = hasta[i].r; n.collR = n.r; n.homeX = n.x; n.homeY = n.y; resizeNodeVisual(n); });
      updatePositions();
    }
  }
  animacionRed = requestAnimationFrame(paso);
}

function toggleNodoApagado(id) {
  if (nodosApagados.has(id)) nodosApagados.delete(id);
  else nodosApagados.add(id);
  aplicarFuerzaNodal();
  // refresca la ficha con el grado ANTES → DESPUÉS y el botón actualizado.
  // HUMEDALES no: su ficha abre la vista ampliada de humedales y taparía la
  // red justo cuando se quiere ver cómo se reacomoda.
  if (id !== "la-vaca") showNodeInfo(id);
}

/* Botones de la barra: apagar/encender toda la red o solo sus hubs. */
function apagarTodosLosNodos() {
  DISPLAY_NODES.forEach(n => nodosApagados.add(n.id));
  aplicarFuerzaNodal();
}
function encenderTodosLosNodos() {
  nodosApagados.clear();
  aplicarFuerzaNodal();
}
function apagarHubs() {
  HUB_IDS.forEach(id => { if (DISPLAY_NODE_IDS.has(id)) nodosApagados.add(id); });
  aplicarFuerzaNodal();
}
function actualizarInfoSimulacion() {
  const el = document.getElementById("m2SimInfo");
  if (!el) return;
  const d = computeDegrees(nodosApagados);
  const encendidos = DISPLAY_NODES.filter(n => !nodosApagados.has(n.id));
  const aristas = RAW_EDGES.filter(e => e.tipo !== "vacio" && relacionVisible(e) &&
    !nodosApagados.has(e.s) && !nodosApagados.has(e.t)).length;
  const sueltos = encendidos.filter(n => (d[n.id] || 0) === 0).length;
  el.textContent = nodosApagados.size === 0
    ? "Un clic abre la ficha · dos clics iluminan sus conexiones · tres clics apagan el nodo y la red se reacomoda."
    : encendidos.length === 0
      ? "La red completa apagada: 0 de " + DISPLAY_NODES.length + " nodos activos y ninguna relación en pie."
      : encendidos.length + " de " + DISPLAY_NODES.length + " nodos activos · " + aristas + " relaciones vigentes · " +
        sueltos + " elemento" + (sueltos === 1 ? "" : "s") + " sin ninguna relación";
}

/* El motor de arrastre trabaja SOLO sobre la red dibujada: los elementos
   del inventario que no se muestran no tienen posición, y mezclarlos aquí
   metía NaN en las fuerzas y descolocaba la red al arrastrar. */
let physicsRunning = false;
function physicsStep() {
  let moving = false;

  // 0. GLOBAL REPULSION (all pairs) - ULTRA EXTREME to push nodes apart
  for (let i = 0; i < DISPLAY_NODES.length; i++) {
    for (let j = i + 1; j < DISPLAY_NODES.length; j++) {
      const a = DISPLAY_NODES[i], b = DISPLAY_NODES[j];
      const dx = b.x - a.x, dy = b.y - a.y;
      const dist = Math.hypot(dx, dy) || 0.1;
      // MASSIVE repulsion: inverse square law
      const repelForce = (PHYSICS.repulsion * 800) / (dist * dist);
      const fx = (dx / dist) * repelForce, fy = (dy / dist) * repelForce;
      if (!a.fixed) { a.vx -= fx; a.vy -= fy; }
      if (!b.fixed) { b.vx += fx; b.vy += fy; }
      moving = true;
    }
  }

  // 1. SPRING FORCES (edges only) - WEAK
  RAW_EDGES.forEach(edge => {
    // solo las relaciones de la red dibujada: los elementos del inventario
    // que no se muestran no tienen posición y contaminarían las fuerzas
    if (!relacionVisible(edge)) return;
    const s = nodeById(edge.s), t = nodeById(edge.t);
    if (!s || !t) return;
    const dx = t.x - s.x, dy = t.y - s.y;
    const dist = Math.hypot(dx, dy) || 1;
    const targetDist = edge.restLength * PHYSICS.linkDistance; // 3x
    const diff = (dist - targetDist) * PHYSICS.spring;
    const fx = (dx / dist) * diff, fy = (dy / dist) * diff;
    if (!s.fixed) { s.vx += fx; s.vy += fy; }
    if (!t.fixed) { t.vx -= fx; t.vy -= fy; }
  });

  // 2. WEAK ANCHOR (barely pulls back)
  DISPLAY_NODES.forEach(n => {
    if (n.fixed) { n.vx = 0; n.vy = 0; return; }
    n.vx += (n.homeX - n.x) * PHYSICS.anchor;
    n.vy += (n.homeY - n.y) * PHYSICS.anchor;
  });

  // 3. DAMPING
  DISPLAY_NODES.forEach(n => {
    if (n.fixed) return;
    n.vx *= PHYSICS.damping;
    n.vy *= PHYSICS.damping;
    n.x += n.vx;
    n.y += n.vy;
    if (Math.abs(n.vx) > PHYSICS.minVel || Math.abs(n.vy) > PHYSICS.minVel) moving = true;
  });

  // 4. STRICT BOUNDS
  DISPLAY_NODES.forEach(n => {
    const margin = n.r + 5;
    if (n.x < margin) { n.x = margin; n.vx = Math.abs(n.vx) * 0.5; }
    if (n.x > CANVAS.w - margin) { n.x = CANVAS.w - margin; n.vx = -Math.abs(n.vx) * 0.5; }
    if (n.y < margin) { n.y = margin; n.vy = Math.abs(n.vy) * 0.5; }
    if (n.y > CANVAS.h - margin) { n.y = CANVAS.h - margin; n.vy = -Math.abs(n.vy) * 0.5; }
  });

  // 5. MANDATORY COLLISION ENFORCEMENT - NO TOUCHING ALLOWED
  for (let i = 0; i < DISPLAY_NODES.length; i++) {
    for (let j = i + 1; j < DISPLAY_NODES.length; j++) {
      const a = DISPLAY_NODES[i], b = DISPLAY_NODES[j];
      const dx = b.x - a.x, dy = b.y - a.y;
      const dist = Math.hypot(dx, dy) || 0.1;
      const minDist = a.r + b.r + 25; // 25px mandatory spacing

      if (dist < minDist) {
        // FORCED SEPARATION: push apart until minDist is satisfied
        const overlap = minDist - dist;
        const pushDist = minDist;
        const nx = dx / dist, ny = dy / dist;

        if (a.fixed && b.fixed) continue;
        if (a.fixed) {
          b.x = a.x + nx * pushDist;
          b.y = a.y + ny * pushDist;
        } else if (b.fixed) {
          a.x = b.x - nx * pushDist;
          a.y = b.y - ny * pushDist;
        } else {
          // Move both apart equally
          a.x -= nx * (overlap / 2);
          a.y -= ny * (overlap / 2);
          b.x += nx * (overlap / 2);
          b.y += ny * (overlap / 2);
        }
        moving = true;
      }
    }
  }

  updatePositions();
  if (moving || DISPLAY_NODES.some(n => n.fixed)) requestAnimationFrame(physicsStep);
  else physicsRunning = false;
}
/* El motor de fuerzas viejo (repulsión "extrema") lanzaba el nodo a otro
   punto del lienzo al soltarlo: se movía, sí, pero terminaba donde nadie lo
   había puesto. Se deja de usar. Al soltar un nodo, la red hace lo que se
   espera: el nodo SE QUEDA donde lo pusieron —ese pasa a ser su sitio— y las
   demás bolas se corren lo justo para que ninguna quede encima de otra. */
function wakePhysics() { /* sin motor de fuerzas: ver acomodarTrasArrastre */ }

function acomodarTrasArrastre(nodoMovido) {
  const nodes = DISPLAY_NODES.filter((n) => !nodosApagados.has(n.id));
  if (!nodes.length) return;
  nodoMovido._origX = nodoMovido.x; nodoMovido._origY = nodoMovido.y;
  nodoMovido.homeX = nodoMovido.x; nodoMovido.homeY = nodoMovido.y;
  const desde = nodes.map((n) => ({ n, x: n.x, y: n.y }));
  separarNodos(nodes, false, 260);
  const hasta = nodes.map((n) => ({ x: n.x, y: n.y }));
  if (animacionRed) cancelAnimationFrame(animacionRed);
  const t0 = performance.now(), DUR = 420;
  const suave = (t) => 1 - Math.pow(1 - t, 3);
  const paso = (ahora) => {
    const k = suave(Math.min(1, (ahora - t0) / DUR));
    nodes.forEach((o, i) => { o.x = desde[i].x + (hasta[i].x - desde[i].x) * k; o.y = desde[i].y + (hasta[i].y - desde[i].y) * k; });
    updatePositions();
    if (k < 1) animacionRed = requestAnimationFrame(paso);
    else {
      animacionRed = null;
      nodes.forEach((o, i) => { o.x = hasta[i].x; o.y = hasta[i].y; o._origX = o.x; o._origY = o.y; o.homeX = o.x; o.homeY = o.y; });
      updatePositions();
    }
  };
  animacionRed = requestAnimationFrame(paso);
}

function attachNodeDragHandler(group, node) {
  const svg = document.getElementById("networkViz");
  let dragging = false, moved = false, startClientX = 0, startClientY = 0;
  let startX = 0, startY = 0, vecinosInicio = [];
  function toSvgPoint(clientX, clientY) {
    const pt = svg.createSVGPoint(); pt.x = clientX; pt.y = clientY;
    const m = svg.getScreenCTM().inverse();
    return pt.matrixTransform(m);
  }
  group.addEventListener("pointerdown", (e) => {
    e.stopPropagation();
    dragging = true; moved = false; startClientX = e.clientX; startClientY = e.clientY;
    startX = node.x; startY = node.y;
    // Los vecinos conectados a este nodo se dejan llevar con él: se guarda
    // su posición de arranque para calcular cuánto los arrastra el tirón.
    const idsVecinos = VECINOS_DIRECTOS.get(node.id) || [];
    vecinosInicio = idsVecinos
      .map((id) => nodeById(id))
      .filter((n) => n && !nodosApagados.has(n.id))
      .map((n) => ({ n, x0: n.x, y0: n.y }));
    // El motor de fuerzas se despierta solo si de verdad se arrastra: con un
    // clic simple la red se quedaba temblando y reacomodándose sola.
    node.fixed = true; group.classList.add("dragging"); group.setPointerCapture(e.pointerId);
  });
  group.addEventListener("pointermove", (e) => {
    if (!dragging) return;
    if (Math.hypot(e.clientX - startClientX, e.clientY - startClientY) > 4) moved = true;
    const p = toSvgPoint(e.clientX, e.clientY);
    node.x = p.x; node.y = p.y; node.homeX = p.x; node.homeY = p.y; node.vx = 0; node.vy = 0;
    // Tirón parcial hacia sus vecinos directos: se mueven una fracción de lo
    // mismo que el nodo arrastrado, para que se sienta la conexión sin que
    // toda la red se mueva en bloque.
    const dx = node.x - startX, dy = node.y - startY;
    const TIRON = 0.35;
    vecinosInicio.forEach(({ n, x0, y0 }) => {
      n.x = x0 + dx * TIRON; n.y = y0 + dy * TIRON; n.homeX = n.x; n.homeY = n.y; n.vx = 0; n.vy = 0;
    });
    updatePositions();
  });
  function endDrag(e) {
    if (!dragging) return;
    dragging = false; node.fixed = false; group.classList.remove("dragging");
    try { group.releasePointerCapture(e.pointerId); } catch (err) {}
    if (moved) acomodarTrasArrastre(node);
    if (moved) { group.dataset.suppressClick = "1"; setTimeout(() => { delete group.dataset.suppressClick; }, 0); }
    vecinosInicio = [];
  }
  group.addEventListener("pointerup", endDrag);
  group.addEventListener("pointercancel", endDrag);
}

let zoomLevel = 1;
let panX = 0, panY = 0;

function updateZoomDisplay() {
  const el = document.getElementById("networkZoomLevel");
  if (el) el.textContent = Math.round(zoomLevel * 100) + "%";
}

function renderNetwork() {
  const svg = document.getElementById("networkViz");
  if (!svg) return;

  svg.innerHTML = "";

  // Build defs first at SVG level
  buildDefs(svg);

  // Create the zoom-pan wrapper group for visual content
  const zoomPanGroup = document.createElementNS(SVG_NS, "g");
  zoomPanGroup.setAttribute("id", "zoom-pan-group");
  zoomPanGroup.setAttribute("transform", `translate(${panX},${panY}) scale(${zoomLevel})`);
  svg.appendChild(zoomPanGroup);

  // Build visual content into temp group, then move to zoom-pan-group
  const tempG = document.createElementNS(SVG_NS, "g");
  buildAmbientMesh(tempG); drawEdges(tempG); drawNodes(tempG);

  // Move all elements from temp to zoom-pan group
  while (tempG.firstChild) zoomPanGroup.appendChild(tempG.firstChild);
}

/* ==========================================================
   ZOOM A UN GRUPO DE ELEMENTOS — "Explorar relaciones a detalle"
   Acerca la red sobre los humedales de Kennedy (El Burro, La Vaca y
   Techo), los ríos Fucha y Tunjuelo a los que drenan, y los dos
   corredores que los cruzan (Avenida Boyacá y Avenida Ciudad de Cali).
   No cambia la red: solo la encuadra y apaga el resto.
   ========================================================== */
const ZOOM_KENNEDY_IDS = [
  "burro", "la-vaca", "techo", "río-fucha", "río-tunjuelo",
  "avenida-boyacá", "avenida-ciudad-de-cali",
];
let zoomDetalleActivo = false;

/* ==========================================================
   ENCUADRE DEL LIENZO — el viewBox fijo de 2500x1820 hacía que en
   pantallas angostas (un teléfono, o la columna de la red junto a la
   leyenda) la red se dibujara en un rectángulo diminuto en el centro de
   un recuadro negro: se veía vacío. Ahora el encuadre se ajusta a lo que
   la red ocupa de verdad y a la forma del contenedor, así que la red
   siempre llena su espacio.
   ========================================================== */
let VISTA = { x: 0, y: 0, w: CANVAS.w, h: CANVAS.h };

function ajustarEncuadreRed() {
  const svg = document.getElementById("networkViz");
  const capa = svg?.querySelector(".nodes-layer");
  if (!svg || !capa) return;
  let caja;
  try { caja = capa.getBBox(); } catch (e) { return; }
  if (!caja || !caja.width || !caja.height) return;
  const MARGEN = 60;
  let w = caja.width + MARGEN * 2, h = caja.height + MARGEN * 2;
  // El alto del lienzo sigue la forma real de la red (con topes), así la red
  // llena el recuadro en vez de quedar como una franja en medio del negro.
  const ancho = svg.clientWidth;
  if (ancho) {
    // En un teléfono el tablero era un cuadrado de ~300 px y la red no cabía:
    // se le da la mayor parte de la altura de la pantalla.
    const altoMin = ancho < 560 ? Math.min(560, Math.round((window.innerHeight || 700) * 0.62)) : 300;
    const altoIdeal = Math.round(Math.max(altoMin, Math.min(820, ancho * h / w)));
    svg.style.height = altoIdeal + "px";
  }
  const cara = svg.clientWidth && svg.clientHeight ? svg.clientWidth / svg.clientHeight : w / h;
  if (w / h > cara) h = w / cara; else w = h * cara;
  VISTA = {
    x: caja.x + caja.width / 2 - w / 2,
    y: caja.y + caja.height / 2 - h / 2,
    w, h,
  };
  svg.setAttribute("viewBox", `${VISTA.x.toFixed(1)} ${VISTA.y.toFixed(1)} ${w.toFixed(1)} ${h.toFixed(1)}`);

  // Si al encuadrar toda la red las bolas quedan diminutas (un teléfono, una
  // ventana angosta), se arranca acercado a un tamaño legible y se recorre
  // arrastrando; el botón de alejar devuelve la vista completa.
  if (!ajustarEncuadreRed._zoomInicialHecho && svg.clientWidth && svg.clientWidth < 760) {
    ajustarEncuadreRed._zoomInicialHecho = true;
    const escala = svg.clientWidth / w;
    const rMin = Math.min(...DISPLAY_NODES.map((n) => n.r || 0).filter((r) => r > 0));
    const diametro = 2 * rMin * escala;
    // se acerca lo justo para que la bola más pequeña se lea, sin perder de
    // vista el resto de la red (con 360% solo se veían dos bolas)
    if (diametro > 0 && diametro < 30) {
      zoomLevel = Math.max(1, Math.min(2.1, 30 / diametro));
      // el acercamiento se hace SOBRE EL CENTRO de la red: si no, el zoom
      // empuja el dibujo fuera de cuadro y el teléfono abre en un vacío
      const cx = caja.x + caja.width / 2, cy = caja.y + caja.height / 2;
      panX = (VISTA.x + VISTA.w / 2) - zoomLevel * cx;
      panY = (VISTA.y + VISTA.h / 2) - zoomLevel * cy;
      const g = svg.querySelector("#zoom-pan-group");
      if (g) g.setAttribute("transform", `translate(${panX},${panY}) scale(${zoomLevel})`);
      updateZoomDisplay();
    }
  }
}

function irAZoomDe(ids, ms) {
  const svg = document.getElementById("networkViz");
  const group = svg?.querySelector("#zoom-pan-group");
  if (!svg || !group) return;
  const nodos = ids.map(nodeById).filter(n => n && n._el);
  if (!nodos.length) return;
  const x0 = Math.min(...nodos.map(n => n.x - n.r)), x1 = Math.max(...nodos.map(n => n.x + n.r));
  const y0 = Math.min(...nodos.map(n => n.y - n.r)), y1 = Math.max(...nodos.map(n => n.y + n.r));
  const margen = 70;   // el encuadre se ceñía demasiado poco al grupo
  const escala = Math.max(0.5, Math.min(6,
    Math.min(VISTA.w / (x1 - x0 + margen * 2), VISTA.h / (y1 - y0 + margen * 2))));
  const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
  const destino = {
    z: escala,
    x: VISTA.x + VISTA.w / 2 - cx * escala,
    y: VISTA.y + VISTA.h / 2 - cy * escala,
  };
  const desde = { z: zoomLevel, x: panX, y: panY };
  const t0 = performance.now(), DUR = ms || 900;
  const suave = (t) => t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
  function paso(ahora) {
    const k = suave(Math.min(1, (ahora - t0) / DUR));
    zoomLevel = desde.z + (destino.z - desde.z) * k;
    panX = desde.x + (destino.x - desde.x) * k;
    panY = desde.y + (destino.y - desde.y) * k;
    group.setAttribute("transform", `translate(${panX},${panY}) scale(${zoomLevel})`);
    updateZoomDisplay();
    if (k < 1) requestAnimationFrame(paso);
  }
  requestAnimationFrame(paso);
}

function explorarRelacionesDetalle() {
  const btn = document.getElementById("btnExplorarRelaciones");
  if (zoomDetalleActivo) {   // segundo clic: se vuelve a ver toda la red
    zoomDetalleActivo = false;
    clearSpotlight();
    btn?.classList.remove("active");
    const svg = document.getElementById("networkViz");
    const group = svg?.querySelector("#zoom-pan-group");
    const desde = { z: zoomLevel, x: panX, y: panY };
    const t0 = performance.now();
    const paso = (ahora) => {
      const k = Math.min(1, (ahora - t0) / 700);
      zoomLevel = desde.z + (1 - desde.z) * k;
      panX = desde.x * (1 - k); panY = desde.y * (1 - k);
      group?.setAttribute("transform", `translate(${panX},${panY}) scale(${zoomLevel})`);
      updateZoomDisplay();
      if (k < 1) requestAnimationFrame(paso);
    };
    requestAnimationFrame(paso);
    return;
  }
  zoomDetalleActivo = true;
  btn?.classList.add("active");
  // ilumina los elementos del acercamiento (y sus relaciones entre sí)
  setSpotlightNodes(ZOOM_KENNEDY_IDS, false);
  irAZoomDe(ZOOM_KENNEDY_IDS);
}

function setupZoomPan() {
  const svg = document.getElementById("networkViz");
  if (!svg) return;

  /* Arrastre del lienzo: sin esto, al acercar la red no había forma de
     moverse por ella (y en un teléfono era la única manera de recorrerla).
     Solo actúa cuando el gesto empieza en el fondo, no sobre un nodo. */
  let arrastrando = false, x0 = 0, y0 = 0, pan0x = 0, pan0y = 0;
  const aplicar = () => {
    const g = svg.querySelector("#zoom-pan-group");
    if (g) g.setAttribute("transform", `translate(${panX},${panY}) scale(${zoomLevel})`);
  };
  let capturado = false;
  svg.addEventListener("pointerdown", (ev) => {
    if (ev.target.closest(".ods-node")) return;   // los nodos tienen su propio arrastre
    arrastrando = true; capturado = false;
    x0 = ev.clientX; y0 = ev.clientY; pan0x = panX; pan0y = panY;
  });
  svg.addEventListener("pointermove", (ev) => {
    if (!arrastrando) return;
    // El lienzo solo empieza a moverse cuando de verdad se arrastra: si se
    // capturara el puntero desde el primer toque, el clic nunca llegaría a la
    // línea de una relación y no se podría abrir su ficha.
    if (!capturado) {
      if (Math.hypot(ev.clientX - x0, ev.clientY - y0) < 4) return;
      capturado = true;
      svg.classList.add("m2-arrastrando");
      try { svg.setPointerCapture(ev.pointerId); } catch (e) {}
    }
    const caja = svg.getBoundingClientRect();
    const escala = caja.width ? VISTA.w / caja.width : 1;   // pantalla -> lienzo
    panX = pan0x + (ev.clientX - x0) * escala;
    panY = pan0y + (ev.clientY - y0) * escala;
    aplicar();
  });
  const fin = (ev) => {
    if (!arrastrando) return;
    arrastrando = false; svg.classList.remove("m2-arrastrando");
    if (capturado) { try { svg.releasePointerCapture(ev.pointerId); } catch (e) {} }
    capturado = false;
  };
  svg.addEventListener("pointerup", fin);
  svg.addEventListener("pointercancel", fin);
  svg.addEventListener("pointerleave", fin);

  // La red queda estática: sin zoom manual (ni con la rueda del mouse ni
  // con los botones +/−, que por eso se ocultan en el CSS). El único cambio
  // de escala que queda es el "enfoque" guiado al hacer clic/doble clic en
  // el fondo (una función curada, no un control libre de zoom).

  let backgroundFocusState = 0;
  let backgroundClickTimer = null;
  const focusIds = (ids, level, text) => {
    const points = ids.map(id => NODE_POS[id]).filter(Boolean);
    if (!points.length) return;
    const center = points.reduce((acc, p) => [acc[0] + p.x / points.length, acc[1] + p.y / points.length], [0, 0]);
    zoomLevel = level;
    panX = CANVAS.w / 2 - center[0] * zoomLevel;
    panY = CANVAS.h / 2 - center[1] * zoomLevel;
    const group = svg.querySelector("#zoom-pan-group");
    if (group) group.setAttribute("transform", `translate(${panX},${panY}) scale(${zoomLevel})`);
    updateZoomDisplay();
    svg.setAttribute("aria-label", text);
  };
  const resetNetworkView = () => {
    zoomLevel = 1; panX = 0; panY = 0; backgroundFocusState = 0;
    const group = svg.querySelector("#zoom-pan-group");
    if (group) group.setAttribute("transform", `translate(${panX},${panY}) scale(${zoomLevel})`);
    updateZoomDisplay();
    svg.setAttribute("aria-label", "Red completa del POT");
  };
  svg.addEventListener("click", (ev) => {
    if (ev.target.closest?.(".ods-node, .edge-group")) return;
    window.clearTimeout(backgroundClickTimer);
    backgroundClickTimer = window.setTimeout(() => {
      if (backgroundFocusState === 0) {
        focusIds(["río-tunjuelo", "río-fucha", "burro", "la-vaca"], 2.15, "Enfoque hídrico: río Tunjuelo, río Fucha, humedal El Burro y humedal La Vaca");
        backgroundFocusState = 1;
      } else resetNetworkView();
    }, 230);
  });
  svg.addEventListener("dblclick", (ev) => {
    if (ev.target.closest?.(".ods-node, .edge-group")) return;
    window.clearTimeout(backgroundClickTimer);
    focusIds(["primera-linea-metro", "segunda-linea-metro", "avenida-boyacá", "avenida-ciudad-de-cali"], 2.05, "Enfoque del Metro: primera y segunda línea");
    backgroundFocusState = 2;
  });

  // Pan con clic del mouse (botón del medio o Shift+arrastre)
  let isPanning = false;
  let startX = 0, startY = 0;
  let startPanX = 0, startPanY = 0;

  svg.addEventListener("mousedown", (ev) => {
    // Solo pan con botón del medio (button 1) o cuando se sostiene Shift
    if (ev.button !== 1 && !ev.getModifierState("Shift")) return;
    // No pan si se hace clic en un nodo o borde
    if (ev.target.closest(".ods-node") || ev.target.closest(".edge-group")) return;
    isPanning = true;
    startX = ev.clientX;
    startY = ev.clientY;
    startPanX = panX;
    startPanY = panY;
  });

  document.addEventListener("mousemove", (ev) => {
    if (!isPanning) return;
    const dx = ev.clientX - startX;
    const dy = ev.clientY - startY;
    panX = startPanX + dx;
    panY = startPanY + dy;
    const group = svg.querySelector("#zoom-pan-group");
    if (group) group.setAttribute("transform", `translate(${panX},${panY}) scale(${zoomLevel})`);
  });

  document.addEventListener("mouseup", () => {
    isPanning = false;
  });

  updateZoomDisplay();
}

/* -------- paneles de información -------- */
function fuenteBadgeHTML(fuente) {
  const st = FUENTE_STYLE[fuente] || FUENTE_STYLE.inferencia;
  return `<span class="fuente-badge" style="color:${st.color};background:${st.color}22;border:1px solid ${st.color}55;"><i class="fa-solid ${st.icon}"></i> ${st.label}</span>`;
}
function relacionBadgeHTML(relacion) {
  if (!relacion || !RELACION_STYLE[relacion]) return "";
  const st = RELACION_STYLE[relacion];
  return `<span class="fuente-badge" style="color:${st.color};background:${st.color}22;border:1px solid ${st.color}55;"><i class="fa-solid fa-arrow-right-arrow-left"></i> ${st.label}</span>`;
}

function showEdgeInfo(index) {
  const edge = RAW_EDGES[index];
  const s = nodeById(edge.s), t = nodeById(edge.t);
  document.querySelectorAll(".edge-group").forEach(el => el.classList.remove("edge-selected"));
  document.querySelector(`.edge-group[data-index="${index}"]`)?.classList.add("edge-selected");
  document.querySelectorAll(".ods-node").forEach(el => el.classList.remove("node-selected"));

  const label = (n) => n.name.replace(/\n/g, " ");
  document.getElementById("edgeInfoTitle").textContent = `${label(s)} → ${label(t)}`;
  const typeEl = document.getElementById("edgeInfoType");
  const color = edgeColor(edge);
  typeEl.innerHTML = TYPE_STYLE[edge.tipo].label + (edge.cat ? " · " + edge.cat.toUpperCase() : "");
  typeEl.style.color = color; typeEl.style.background = color + "26";

  document.getElementById("edgeInfoFuente").innerHTML = fuenteBadgeHTML(edge.fuente) + " " + relacionBadgeHTML(edge.relacion);
  document.getElementById("edgeInfoQuote").textContent = edge.cita ? edge.cita : "(No hay cita literal disponible para esta relación — ver análisis abajo.)";
  document.getElementById("edgeInfoAnalisis").textContent = edge.analisis || "";
  // De dónde sale la relación: artículo y página cuando el POT la enuncia; y
  // si no, se dice con esas palabras en vez de dejar un "sin artículo" seco.
  const donde = [];
  if (edge.articulo) donde.push(edge.articulo);
  if (edge.pagina && edge.pagina !== "—") donde.push("p. " + edge.pagina);
  document.getElementById("edgeInfoPage").textContent = donde.length
    ? "Dónde aparece en el POT: " + donde.join(" · ")
    : (edge.fuente === "inventario_pendiente"
        ? "El POT no enuncia esta relación: está en el inventario del equipo, pendiente de localizar la frase."
        : "Sin artículo ni página localizados todavía.");
  document.getElementById("edgeInfoPanel").classList.add("visible");
  document.getElementById("nodeInfoPanel")?.classList.remove("visible");

  document.querySelectorAll(".matrix-row[data-edge]").forEach(row => row.classList.toggle("row-highlight", Number(row.dataset.edge) === index));

  // se iluminan los dos elementos que la relación une, y se apaga el resto
  setSpotlightNodes([edge.s, edge.t], false);
}
function hideEdgeInfo() {
  document.getElementById("edgeInfoPanel").classList.remove("visible");
  document.querySelectorAll(".edge-group").forEach(el => el.classList.remove("edge-selected"));
  document.querySelectorAll(".matrix-row[data-edge]").forEach(row => row.classList.remove("row-highlight"));
}

function escapeTexto(t) {
  return String(t).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function showNodeInfo(id) {
  const node = nodeById(id);
  if (!node) return;
  document.querySelectorAll(".ods-node").forEach(el => el.classList.remove("node-selected"));
  document.querySelector(`.ods-node[data-id="${id}"]`)?.classList.add("node-selected");

  const apagado = nodosApagados.has(id);
  const degActual = computeDegrees(nodosApagados)[id] || 0;
  const degBase = node._degBase !== undefined ? node._degBase : degActual;
  let gradoHTML = `fuerza nodal (grado real): <b>${degActual}</b>`;
  if (!apagado && degActual !== degBase) {
    gradoHTML = `fuerza nodal (grado real): <b>${degBase} → ${degActual}</b> <span style="opacity:.75;">(recalculada al apagar otro nodo)</span>`;
  } else if (apagado) {
    gradoHTML = `fuerza nodal: <b>0</b> — nodo apagado (grado original: ${degBase})`;
  }
  document.getElementById("nodeInfoTitle").textContent = node.name.replace(/\n/g, " ") + (node.suplementario ? " (suplementario)" : "");
  document.getElementById("nodeInfoStruct").innerHTML = `<span class="swatch-tag" style="background:${node.color}"></span> ${STRUCT_STYLE[node.cat].label} · ${gradoHTML}`;
  document.getElementById("nodeInfoFuente").innerHTML = fuenteBadgeHTML(node.fuente);

  const toggleBtn = document.getElementById("nodeInfoToggleBtn");
  if (toggleBtn) {
    toggleBtn.textContent = apagado ? "Encender nodo" : "¿Qué pasaría si se apaga este nodo?";
    toggleBtn.classList.toggle("is-apagado", apagado);
    toggleBtn.onclick = () => toggleNodoApagado(id);
  }

  /* Relaciones del elemento. Antes la ficha tomaba UNA arista cualquiera y
     mostraba su cita, su artículo y su análisis como si fueran del nodo: para
     el HUMEDAL EL BURRO decía "cruce espacial: el corredor vial atraviesa
     este cuerpo de agua", que es el motivo de una de sus relaciones, no lo que
     el POT dice del humedal. Ahora la cita solo se muestra si el POT habla del
     elemento en sí, y cada relación se lista aparte con su propio motivo. */
  const relEdges = RAW_EDGES.filter(e => (e.s === id || e.t === id) && relacionVisible(e));
  const citaPropia = relEdges.find(e => e.fuente === "cita_literal" && e.cita &&
    (String(e.cita).toLowerCase().includes(String(node.name).split("\n")[0].toLowerCase().slice(0, 9))));
  document.getElementById("nodeInfoArticulo").textContent = citaPropia
    ? (citaPropia.articulo || "Documento del POT") + (citaPropia.pagina ? ` · p. ${citaPropia.pagina}` : "")
    : "El POT lo nombra, pero sin un artículo localizado para el elemento en sí.";
  document.getElementById("nodeInfoQuote").textContent = citaPropia ? citaPropia.cita
    : "El respaldo documental de este elemento está en cada una de sus relaciones, abajo.";
  document.getElementById("nodeInfoNota").textContent = node.suplementario
    ? "Nodo suplementario: no forma parte de la Matriz completa (Excel) del equipo, pero se incluye por su valor narrativo."
    : "";

  const cont = document.getElementById("nodeInfoRelaciones");
  if (cont) {
    const vivas = relEdges.filter(e => e.tipo !== "vacio" && !nodosApagados.has(e.s) && !nodosApagados.has(e.t));
    const fila = (e) => {
      const otroId = e.s === id ? e.t : e.s;
      const otro = nodeById(otroId);
      if (!otro) return "";
      const donde = e.articulo || (e.pagina && e.pagina !== "—" ? "p. " + e.pagina : null);
      const i = RAW_EDGES.indexOf(e);
      return `<button type="button" class="node-rel-fila" data-arista="${i}">
        <span class="node-rel-nombre"><i class="node-rel-punto" style="background:${otro.color}"></i>${otro.name.replace(/\n/g, " ")}</span>
        <span class="node-rel-motivo">${escapeTexto(e.analisis || "")}</span>
        <span class="node-rel-donde">${e.fuente === "cita_literal" ? "Frase del POT" : "Sin frase del POT"}${donde ? " · " + donde : ""}</span>
      </button>`;
    };
    cont.innerHTML = vivas.length
      ? `<p class="node-rel-titulo">Por qué se conecta (${vivas.length} ${vivas.length === 1 ? "relación" : "relaciones"})</p>` + vivas.map(fila).join("")
      : `<p class="node-rel-titulo">Sin relaciones vigentes en este momento.</p>`;
    cont.querySelectorAll(".node-rel-fila").forEach((btn) => {
      btn.addEventListener("click", (ev) => { ev.stopPropagation(); showEdgeInfo(Number(btn.dataset.arista)); });
    });
  }

  document.getElementById("nodeInfoMapaWrap").style.display = "none";

  document.getElementById("nodeInfoPanel").classList.add("visible");
  document.getElementById("edgeInfoPanel")?.classList.remove("visible");
}

