const MOVILIDAD_CONCLUSION = "El POT sí plantea que el Metro debe generar conexiones entre distintos ambitos. Sin embargo, al construir su red, algunos componentes aparecen como hubs centrales y otros quedan periféricos, conectados solo a un proyecto o a una estructura específica. Esta distribución desigual muestra que el POT reconoce relaciones, pero no las articula completamente como una red territorial integrada. Además, sus planos representan principalmente líneas, estaciones y localizaciones, sin mostrar cómo esas conexiones funcionan en el tiempo, quién depende de ellas, qué recorridos se producen ni qué ocurre cuando la red se congestiona o falla.";

let movilidadPopupAnchor = null;
let movilidadClickOutsideWired = false;

function showMovilidadOverlay(opts) {
  const animateIn = !!(opts && opts.animateIn);
  // El panel lateral de este zoom reemplaza a la leyenda de la red inicial.
  const legendM = document.getElementById("networkLegend");
  if (legendM) legendM.style.display = "none";
  const actsM = document.getElementById("networkSidebarActions");
  if (actsM) actsM.style.display = "none";
  const panelM = document.getElementById("movilidadPanelLateral");
  if (panelM) panelM.style.display = "";
  hideNodeInfo();
  hideEdgeInfo();
  document.querySelector(".network-canvas").style.display = "none";
  document.getElementById("humedalesOverlay").style.display = "none";

  const body = document.getElementById("movilidadOverlayBody");

  // Las bolas naranjas de la foto se COPIAN encima, una por una, con el mismo
  // tamaño y posición: fondo negro, letra blanca y aro naranja con leve brillo.
  const highlightRingsHTML = Object.entries(MOVILIDAD_CIRCULOS)
    .map(([key, c]) => `
      <div class="movilidad-bola" data-key="${key}"
        style="left:${c.x}%; top:${c.y}%; width:${c.diam}%; height:${(c.diam * MOVILIDAD_ASPECT).toFixed(3)}%;">
        <span>${(c.label || "").replace(/\n/g, "<br>")}</span>
      </div>
    `).join("");

  // Cada línea (metro, RegioTram, corredor verde) es una máscara-imagen
  // calcada pixel a pixel de la línea real ya dibujada en la foto del POT —
  // se superpone exactamente encima de la foto base (mismas dimensiones,
  // mismo encuadre), con su color propio y un glow neón vía CSS. Un botón
  // invisible sobre su área de influencia dispara el popup con la cita.
  const lineasHTML = MOVILIDAD_CORREDORES_NEON.map(l => `
    <img class="movilidad-neon-line-img" data-corredor="${l.id}" src="${l.img}"
      style="--neon-color:${l.color};" alt="" />
  `).join("");
  const trazoRosaHTML = `
    <svg class="movilidad-trazo-rosa" viewBox="0 0 100 ${MOVILIDAD_VIEWBOX_H}" preserveAspectRatio="none">
      ${MOVILIDAD_LINEAS_ROSA.map(l => { const pts = l.puntos.map(p => p[0] + "," + (p[1] * MOVILIDAD_VIEWBOX_H / 100)).join(" "); return `<polyline class="movilidad-line-${l.id}" data-linea="${l.id}" style="--linea-color:${l.color}" points="${pts}" /><polyline class="movilidad-trazo-hit" data-linea="${l.id}" points="${pts}" />${l.etiqueta ? `<text class="movilidad-line-label" x="${l.puntos[Math.min(3, l.puntos.length - 1)][0]}" y="${(l.puntos[Math.min(3, l.puntos.length - 1)][1] * MOVILIDAD_VIEWBOX_H / 100) - 1.6}" fill="${l.color}">${l.etiqueta}</text>` : ""}`; }).join("")}
      ${MOVILIDAD_CORREDORES_NEON.filter(l => l.hitPuntos).map(l => { const pts = l.hitPuntos.map(p => p[0] + "," + (p[1] * MOVILIDAD_VIEWBOX_H / 100)).join(" "); return `<polyline class="movilidad-trazo-hit" data-corredor="${l.id}" points="${pts}" />`; }).join("")}
    </svg>`;
  const lineaHotspotsHTML = [].map(l => `
    <button type="button" class="movilidad-line-hotspot" data-corredor="${l.id}"
      style="left:${l.anchor[0]}%; top:${l.anchor[1]}%; --neon-color:${l.color};" title="${l.titulo}">
      <i class="fa-solid fa-circle-dot"></i>
    </button>
  `).join("");

  // La única relación sin trazo propio dibujado (RegioTram↔Metro) se marca
  // con un pequeño punto clicable sobre el cruce real de esas dos líneas.
  const hotspotsHTML = Object.entries(MOVILIDAD_RELACIONES).filter(([, rel]) => !rel.sinPunto).map(([key, rel]) => `
    <button type="button" class="movilidad-hotspot" data-key="${key}" style="left:${rel.x}%; top:${rel.y}%;" title="${rel.titulo}">
      <i class="fa-solid fa-circle-dot"></i>
    </button>
  `).join("");

  const imgWrap = document.createElement("div");
  imgWrap.className = "movilidad-overlay-image-wrap";
  imgWrap.id = "movilidadImageWrap";
  imgWrap.innerHTML = `
    <div class="movilidad-overlay-image-frame" id="movilidadImageFrame">
      <img id="movilidadOverlayImg" src="${MOVILIDAD_MAP_IMG_B64}" alt="Plano del sistema de movilidad del POT" class="movilidad-overlay-image" />
      <div class="movilidad-overlay-lines">${lineasHTML}</div>
      ${trazoRosaHTML}
      ${highlightRingsHTML}
      ${hotspotsHTML}
      ${lineaHotspotsHTML}
    </div>
    <div class="movilidad-popup" id="movilidadPopup" style="display:none;"></div>
  `;
  // Inserta el wrap de la imagen ANTES del sidebar (que ya vive en el HTML
  // estático), para no perder la nota naranja + botón de conclusión al
  // regenerar el contenido dinámico cada vez que se abre el overlay.
  const existingWrap = document.getElementById("movilidadImageWrap");
  if (existingWrap) existingWrap.remove();
  body.insertBefore(imgWrap, body.firstChild);

  requestAnimationFrame(() => {
    fitMovilidadFrame();
  });

  body.querySelectorAll(".movilidad-hotspot").forEach(btn => {
    btn.addEventListener("click", (ev) => {
      ev.stopPropagation();
      const key = btn.dataset.key;
      const rel = MOVILIDAD_RELACIONES[key];
      if (!rel) return;
      showMovilidadRelacionDetalle(rel, btn);
      body.querySelectorAll(".movilidad-hotspot").forEach(b => b.classList.remove("active"));
      btn.classList.add("active");
    });
  });
  body.querySelectorAll(".movilidad-trazo-hit").forEach(hit => {
    hit.addEventListener("click", (ev) => {
      ev.stopPropagation();
      if (hit.dataset.corredor) { showMovilidadCorredorDetalle(hit.dataset.corredor); return; }
      const linea = MOVILIDAD_LINEAS_ROSA.find(l => l.id === hit.dataset.linea);
      const rel = MOVILIDAD_RELACIONES[linea?.rel || "primera_linea_metro"];
      if (rel) showMovilidadRelacionDetalle(rel, hit);
    });
  });
  // --- Modo edición de líneas (tecla L): arrastra los vértices, "Copiar"
  // imprime las coordenadas en consola para pegarlas en el código. ---
  wireMovilidadEdicionLineas(body);
  body.querySelectorAll(".movilidad-line-hotspot").forEach(btn => {
    btn.addEventListener("click", (ev) => {
      ev.stopPropagation();
      showMovilidadCorredorDetalle(btn.dataset.corredor);
      body.querySelectorAll(".movilidad-line-hotspot").forEach(b => b.classList.remove("active"));
      btn.classList.add("active");
    });
  });

  document.getElementById("movilidadConclusionBtn")?.addEventListener("click", showMovilidadConclusionPopup);

  if (!movilidadClickOutsideWired) {
    movilidadClickOutsideWired = true;
    document.getElementById("movilidadOverlayBody")?.addEventListener("click", (ev) => {
      if (!ev.target.closest(".movilidad-hotspot") && !ev.target.closest(".movilidad-line-hotspot") &&
          !ev.target.closest(".movilidad-trazo-hit") &&
          !ev.target.closest("#movilidadPopup") && !ev.target.closest("#movilidadConclusionBtn")) {
        hideMovilidadPopup();
      }
    });
  }

  const overlayEl = document.getElementById("movilidadOverlay");
  overlayEl.style.display = "flex";
  if (animateIn) {
    overlayEl.classList.remove("overlay-entering");
    // Dos rAF (no un simple reflow síncrono) para garantizar que el navegador
    // ya pintó el frame con display:flex antes de arrancar la animación —
    // evita que la animación quede "congelada" en el tiempo 0 cuando se
    // dispara justo dentro de otro evento de transición encadenado.
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        overlayEl.classList.add("overlay-entering");
        const clear = () => overlayEl.classList.remove("overlay-entering");
        overlayEl.addEventListener("animationend", clear, { once: true });
        setTimeout(clear, 700); // red de seguridad: nunca dejar el overlay pegado en opacity 0
      });
    });
  }
}
function hideMovilidadOverlay() {
  const legendM = document.getElementById("networkLegend");
  if (legendM) legendM.style.display = "";
  const actsM = document.getElementById("networkSidebarActions");
  if (actsM) actsM.style.display = "";
  const panelM = document.getElementById("movilidadPanelLateral");
  if (panelM) panelM.style.display = "none";
  document.getElementById("movilidadOverlay").style.display = "none";
  document.querySelector(".network-canvas").style.display = "";
  hideMovilidadPopup();
}

/* Ajusta el frame de la imagen (16:9 real) para que ocupe el máximo espacio
   posible dentro de movilidad-overlay-image-wrap — mismo patrón que
   fitImageFrame() para humedales. */
function fitMovilidadFrame() {
  const wrap = document.getElementById("movilidadImageWrap");
  const frame = document.getElementById("movilidadImageFrame");
  if (!wrap || !frame) return;
  const wrapW = wrap.clientWidth, wrapH = wrap.clientHeight;
  if (!wrapW || !wrapH) return;
  const ratio = MOVILIDAD_ASPECT; // 16:9 — la foto HD nueva sí es 16:9
  let w = wrapW, h = w / ratio;
  if (h > wrapH) { h = wrapH; w = h * ratio; }
  frame.style.width = w + "px";
  frame.style.height = h + "px";
}
window.addEventListener("resize", () => {
  if (document.getElementById("movilidadOverlay")?.style.display === "flex") fitMovilidadFrame();
});

function showMovilidadRelacionDetalle(rel, anchorEl) {
  const html = `
    <div class="movilidad-popup-titulo">${rel.titulo}</div>
    <div class="movilidad-popup-cita">${rel.cita}</div>
    ${rel.pagina ? `<div class="humedal-caso-pagina">${rel.pagina}</div>` : ""}
    <button type="button" class="movilidad-back-btn" id="movilidadPopupCloseBtn">Cerrar</button>
  `;
  showMovilidadPopup(html, rel.x, rel.y);
}

function showMovilidadCorredorDetalle(corredorId) {
  const corredor = MOVILIDAD_CORREDORES_NEON.find(l => l.id === corredorId);
  if (!corredor) return;
  const html = `
    <div class="movilidad-popup-titulo">${corredor.titulo}</div>
    <div class="movilidad-popup-cita">${corredor.cita}</div>
    <button type="button" class="movilidad-back-btn" id="movilidadPopupCloseBtn">Cerrar</button>
  `;
  showMovilidadPopup(html, corredor.anchor[0], corredor.anchor[1]);
}

function showMovilidadConclusionPopup() {
  const html = `
    <div class="movilidad-popup-titulo">Conclusión: la red de movilidad del POT</div>
    <div class="movilidad-popup-cita">${MOVILIDAD_CONCLUSION}</div>
    <button type="button" class="movilidad-back-btn" id="movilidadPopupCloseBtn">Cerrar</button>
  `;
  showMovilidadPopup(html, 50, 50);
}

/* Popup flotante anclado al punto exacto del plano — igual que
   showHumedalPopup, pero además comprueba que no quede encima de ningún
   hotspot ni anillo resaltado del propio plano. */
function showMovilidadPopup(innerHTML, xPct, yPct) {
  const popup = document.getElementById("movilidadPopup");
  const wrap = document.getElementById("movilidadImageWrap");
  const frame = document.getElementById("movilidadImageFrame");
  if (!popup || !wrap || !frame) return;
  movilidadPopupAnchor = { x: xPct, y: yPct };
  popup.innerHTML = innerHTML;
  popup.style.display = "block";
  // Con citas largas el popup podría crecer más que el wrap (que recorta con
  // overflow:hidden), así que se limita a la altura disponible y hace scroll.
  popup.style.maxHeight = Math.max(120, wrap.clientHeight - 12) + "px";

  const wrapRect = wrap.getBoundingClientRect();
  const frameRect = frame.getBoundingClientRect();
  const anchorX = (frameRect.left - wrapRect.left) + (xPct / 100) * frameRect.width;
  const anchorY = (frameRect.top - wrapRect.top) + (yPct / 100) * frameRect.height;

  popup.style.left = "0px";
  popup.style.top = "0px";
  const pw = popup.offsetWidth, ph = popup.offsetHeight;
  const margin = 14;
  const wrapW = wrap.clientWidth, wrapH = wrap.clientHeight;

  const hotspotRects = Array.from(document.querySelectorAll(".movilidad-hotspot, .movilidad-highlight-ring, .movilidad-line-hotspot")).map(el => {
    const r = el.getBoundingClientRect();
    return {
      left: r.left - wrapRect.left, top: r.top - wrapRect.top,
      right: r.right - wrapRect.left, bottom: r.bottom - wrapRect.top,
    };
  });
  const overlapsAnyHotspot = (left, top) => {
    const right = left + pw, bottom = top + ph;
    return hotspotRects.some(h => left < h.right && right > h.left && top < h.bottom && bottom > h.top);
  };
  const clampX = (v) => Math.max(6, Math.min(wrapW - pw - 6, v));
  const clampY = (v) => Math.max(6, Math.min(wrapH - ph - 6, v));

  const candidates = [
    { left: clampX(anchorX + margin), top: clampY(anchorY - ph / 2), flip: false },
    { left: clampX(anchorX - pw - margin), top: clampY(anchorY - ph / 2), flip: true },
    { left: clampX(anchorX - pw / 2), top: clampY(anchorY + margin), flip: false },
    { left: clampX(anchorX - pw / 2), top: clampY(anchorY - ph - margin), flip: false },
  ];
  let chosen = candidates.find(c => !overlapsAnyHotspot(c.left, c.top));
  if (!chosen) {
    chosen = candidates[0];
    for (let step = 1; step <= 40 && overlapsAnyHotspot(chosen.left, chosen.top); step++) {
      const dir = step % 2 === 0 ? 1 : -1;
      const tryTop = clampY(candidates[0].top + dir * step * 10);
      if (!overlapsAnyHotspot(candidates[0].left, tryTop)) { chosen = { ...candidates[0], top: tryTop }; break; }
    }
  }

  popup.style.left = chosen.left + "px";
  popup.style.top = chosen.top + "px";
  popup.classList.toggle("movilidad-popup-flip", chosen.flip);

  document.getElementById("movilidadPopupCloseBtn")?.addEventListener("click", hideMovilidadPopup);
}

function hideMovilidadPopup() {
  const popup = document.getElementById("movilidadPopup");
  if (popup) { popup.style.display = "none"; popup.innerHTML = ""; }
  movilidadPopupAnchor = null;
  document.querySelectorAll(".movilidad-hotspot").forEach(b => b.classList.remove("active"));
}

/* Animación del botón "Ver hallazgos clave": efecto tipo "corte de luz" — los
   nodos y aristas que NO forman parte de la relación
   Transporte Público / Equipamientos / Vivienda / Servicios Empresariales /
   Ciclorutas / Red Vial parpadean y se apagan, mientras esos 6 sobreviven
   con un brillo. Después de un instante, la vista pasa al plano de
   movilidad (segunda pantalla) con un fundido. */
function verHallazgosConAnimacion() {
  document.querySelectorAll(".insight-card").forEach(c => c.classList.remove("active"));

  const survivors = new Set(HALLAZGOS_NODOS_SOBREVIVIENTES);
  const survivorEdges = new Set();
  RAW_EDGES.forEach((edge, i) => {
    if (survivors.has(edge.s) && survivors.has(edge.t)) survivorEdges.add(i);
  });

  document.querySelectorAll(".ods-node").forEach(el => {
    if (!survivors.has(el.dataset.id)) el.classList.add("blackout-flicker");
    else el.classList.add("blackout-surviving");
  });
  document.querySelectorAll(".edge-group").forEach(el => {
    if (!survivorEdges.has(Number(el.dataset.index))) el.classList.add("blackout-flicker");
  });

  setTimeout(() => {
    // Deja el estado final del "apagón" aplicado con el spotlight normal
    // (mismo sistema que usan los demás hallazgos), y limpia las clases de
    // animación para no repetir el parpadeo si se vuelve a esta vista.
    setSpotlightNodes(HALLAZGOS_NODOS_SOBREVIVIENTES, false);
    document.querySelectorAll(".blackout-flicker").forEach(el => el.classList.remove("blackout-flicker"));
    document.querySelectorAll(".blackout-surviving").forEach(el => el.classList.remove("blackout-surviving"));

    // Breve pausa para que se vea la red ya "apagada" antes de pasar al plano.
    setTimeout(() => {
      const svg = document.getElementById("networkViz");
      svg?.classList.add("zoom-into-humedales"); // reutiliza la misma animación de acercamiento genérica
      const onDone = () => {
        svg?.removeEventListener("transitionend", onDone);
        showMovilidadOverlay({ animateIn: true });
        svg?.classList.remove("zoom-into-humedales");
        if (svg) svg.style.transformOrigin = "";
      };
      if (svg) {
        svg.style.transformOrigin = "50% 50%";
        svg.addEventListener("transitionend", onDone, { once: true });
        setTimeout(() => { if (svg.classList.contains("zoom-into-humedales")) onDone(); }, 3200);
      } else {
        showMovilidadOverlay({ animateIn: true });
      }
    }, 650);
  }, 950);
}

/* -------- visibilidad / leyenda -------- */
function refreshEdgeVisibility() {
  document.querySelectorAll(".edge-group").forEach(group => {
    const type = group.dataset.type, cat = group.dataset.cat, s = group.dataset.source, t = group.dataset.target;
    const catBits = cat.split("-");
    const hidden = typeOff.has(type) || nodeOff.has(s) || nodeOff.has(t) || catBits.some(c => catOff.has(c));
    group.classList.toggle("hidden-edge", hidden);
  });
  document.querySelectorAll(".ods-node").forEach(node => {
    const cat = node.dataset.cat;
    node.classList.toggle("hidden-node", nodeOff.has(node.dataset.id) || catOff.has(cat));
  });
}
function toggleNode(id) {
  const group = document.querySelector(`.ods-node[data-id="${id}"]`);
  if (!group) return;
  if (nodeOff.has(id)) { nodeOff.delete(id); group.classList.remove("node-off"); }
  else { nodeOff.add(id); group.classList.add("node-off"); }
  refreshEdgeVisibility();
}

function attachNodeClickHandler(group, id) {
  let count = 0, timer = null;
  group.addEventListener("click", (ev) => {
    ev.stopPropagation();
    if (group.dataset.suppressClick) return;
    count++;
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => {
      // 1 clic: ficha del nodo · 2 clics: deja iluminadas sus conexiones ·
      // 3 clics: lo apaga (o lo enciende) y la red se reacomoda.
      if (count === 1) showNodeInfo(id);
      else if (count === 2) toggleNodeFlow(id);
      else if (count >= 3) toggleNodoApagado(id);
      count = 0;
    }, 300);
  });
}

let spotlight = null;
function clearSpotlight() { spotlight = null; document.querySelectorAll(".insight-card").forEach(c => c.classList.remove("active")); applySpotlightState(); }
function setSpotlightNodes(nodeIds, expand) { spotlight = { mode:"nodes", nodes:new Set(nodeIds), expand:!!expand }; applySpotlightState(); }
function setSpotlightTypes(types) { spotlight = { mode:"types", types }; applySpotlightState(); }
function setSpotlightCats(cats) { spotlight = { mode:"cats", cats }; applySpotlightState(); }

function applySpotlightState() {
  let visibleNodes = null, visibleEdges = null;
  if (spotlight && spotlight.mode === "nodes") {
    visibleNodes = new Set(spotlight.nodes); visibleEdges = new Set();
    RAW_EDGES.forEach((edge, i) => {
      const sIn = spotlight.nodes.has(edge.s), tIn = spotlight.nodes.has(edge.t);
      if (spotlight.expand) { if (sIn || tIn) { visibleEdges.add(i); visibleNodes.add(edge.s); visibleNodes.add(edge.t); } }
      else if (sIn && tIn) visibleEdges.add(i);
    });
  } else if (spotlight && spotlight.mode === "types") {
    visibleEdges = new Set(); visibleNodes = new Set();
    RAW_EDGES.forEach((edge, i) => { if (spotlight.types.includes(edge.tipo)) { visibleEdges.add(i); visibleNodes.add(edge.s); visibleNodes.add(edge.t); } });
  } else if (spotlight && spotlight.mode === "cats") {
    visibleNodes = new Set(); visibleEdges = new Set();
    RAW_EDGES.forEach((edge, i) => { if (spotlight.cats.some(c => edge.cat.split("-").includes(c))) { visibleEdges.add(i); visibleNodes.add(edge.s); visibleNodes.add(edge.t); } });
  }
  // Lo que queda fuera se apaga y lo que queda dentro se ENCIENDE: así el
  // doble clic sobre un nodo se lee como "estas son sus conexiones directas",
  // no solo como "el resto se ve más oscuro".
  document.querySelectorAll(".ods-node").forEach(el => {
    const dentro = visibleNodes ? visibleNodes.has(el.dataset.id) : null;
    el.classList.toggle("node-focus-dim", dentro === false);
    el.classList.toggle("node-focus-on", dentro === true);
  });
  document.querySelectorAll(".edge-group").forEach(el => {
    const dentro = visibleEdges ? visibleEdges.has(Number(el.dataset.index)) : null;
    el.classList.toggle("edge-focus-dim", dentro === false);
    el.classList.toggle("edge-focus-on", dentro === true);
  });
}
function toggleNodeFlow(id) {
  const already = spotlight && spotlight.mode === "nodes" && spotlight.expand && spotlight.nodes.size === 1 && spotlight.nodes.has(id);
  if (already) clearSpotlight(); else setSpotlightNodes([id], true);
}

/* ==========================================================
   HUBS vs PERIFÉRICOS — dos botones en la leyenda que responden
   a la pregunta del módulo ("¿qué elementos son realmente
   centrales y cuáles quedan periféricos?"). Reutilizan el mismo
   spotlight de arriba: iluminan el subconjunto elegido y atenúan
   el resto de la red, en vivo y sobre el grado real vigente
   (si hay nodos apagados, la clasificación se recalcula con eso).
   ========================================================== */
function clearControlActive() {
  document.querySelectorAll(".legend-footer-row .control-btn").forEach(b => b.classList.remove("active"));
}
function verHubs() {
  const btn = document.getElementById("btnVerHubs");
  const yaActivo = btn && btn.classList.contains("active");
  clearControlActive();
  if (yaActivo) { clearSpotlight(); return; }
  setSpotlightNodes(HUB_IDS, true); // true = mostrar también sus vecinos directos
  btn?.classList.add("active");
}
function verPerifericos() {
  const btn = document.getElementById("btnVerPerifericos");
  const yaActivo = btn && btn.classList.contains("active");
  clearControlActive();
  if (yaActivo) { clearSpotlight(); return; }
  const deg = computeDegrees(nodosApagados);
  // Periférico = grado real bajo (≤2 conexiones) sobre la red vigente,
  // igual que describe el módulo: "pocas conexiones y baja integración".
  const ids = ODS_NODES.filter(n => (deg[n.id] || 0) <= 2).map(n => n.id);
  setSpotlightNodes(ids, false);
  btn?.classList.add("active");
}

// "Bogotá como sistema complicado" — revela, en un solo panel (texto +
// mapa de ejemplo juntos, sin un segundo click), la idea de que el POT
// DESCOMPONE la ciudad en piezas manejables para poder tomar decisiones
// sobre el territorio, y resalta en la red un ejemplo concreto: "Parques".
function toggleBogotaComplejo() {
  const btn = document.getElementById("btnBogotaComplejo");
  const reveal = document.getElementById("bogotaComplejoReveal");
  if (!btn || !reveal) return;
  const yaActivo = btn.classList.contains("active");
  if (yaActivo) {
    btn.classList.remove("active");
    reveal.hidden = true;
    clearSpotlight();
    return;
  }
  btn.classList.add("active");
  reveal.hidden = false;
  clearControlActive();
  setSpotlightNodes(["parques"], true);
}
// Cerrar el panel al hacer click en el fondo oscuro (fuera de la tarjeta)
document.addEventListener("DOMContentLoaded", () => {
  const reveal = document.getElementById("bogotaComplejoReveal");
  if (reveal) reveal.addEventListener("click", (ev) => {
    if (ev.target === reveal) toggleBogotaComplejo();
  });
});

function toggleInsight(key) {
  const card = document.querySelector(`.insight-card[data-insight="${key}"]`);
  if (!card) return;
  if (card.classList.contains("active")) { clearSpotlight(); return; }
  document.querySelectorAll(".insight-card").forEach(c => c.classList.remove("active"));
  if (key === "todas") { clearSpotlight(); return; }
  if (["directa","indirecta","vacio"].includes(key)) setSpotlightTypes([key]);
  else if (["e1","e2","e3","e4"].includes(key)) setSpotlightCats([key]);
  card.classList.add("active");
}

function setupLegendToggle() {
  document.querySelectorAll(".legend-item input").forEach(input => {
    input.addEventListener("change", (e) => {
      const item = e.target.closest(".legend-item");
      const mode = item.dataset.mode, val = item.dataset.type || item.dataset.cat;
      if (e.target.checked) { if (mode === "type") typeOff.delete(val); else catOff.delete(val); }
      else { if (mode === "type") typeOff.add(val); else catOff.add(val); }
      item.classList.toggle("off", !e.target.checked);
      refreshEdgeVisibility();
    });
  });
  document.getElementById("edgeInfoClose")?.addEventListener("click", hideEdgeInfo);
  document.getElementById("nodeInfoClose")?.addEventListener("click", hideNodeInfo);
  document.getElementById("humedalesOverlayClose")?.addEventListener("click", hideHumedalesOverlay);
  document.getElementById("movilidadOverlayClose")?.addEventListener("click", () => { hideMovilidadOverlay(); clearSpotlight(); });
  document.getElementById("mapa3OverlayClose")?.addEventListener("click", hideMapa3Overlay);
  
  // Selector de mapas (modal de exploración en detalle)
  document.getElementById("modalExplorarClose")?.addEventListener("click", cerrarModalExplorarRelaciones);
  document.getElementById("modalExplorarRelaciones")?.addEventListener("click", (e) => {
    if (e.target.id === "modalExplorarRelaciones") cerrarModalExplorarRelaciones();
  });
  document.getElementById("btnOpcionMapaVias")?.addEventListener("click", abrirMapaVias);
  document.getElementById("btnOpcionMapaHumedales")?.addEventListener("click", abrirMapaHumedales);
  document.getElementById("btnOpcionMapa3")?.addEventListener("click", abrirMapa3);

  window.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      cerrarModalExplorarRelaciones();
    }
  });
}

/* ==========================================================
   MODAL POPUP: SELECTOR DE MAPAS (EXPLORAR RELACIONES EN DETALLE)
   ========================================================== */
function abrirModalExplorarRelaciones() {
  const modal = document.getElementById("modalExplorarRelaciones");
  if (!modal) return;
  modal.style.display = "flex";
  modal.setAttribute("aria-hidden", "false");
}

function cerrarModalExplorarRelaciones() {
  const modal = document.getElementById("modalExplorarRelaciones");
  if (!modal) return;
  modal.style.display = "none";
  modal.setAttribute("aria-hidden", "true");
}

function abrirMapaVias() {
  cerrarModalExplorarRelaciones();
  setTimeout(() => {
    zoomIntoMovilidad();
  }, 40);
}

function abrirMapaHumedales() {
  cerrarModalExplorarRelaciones();
  setTimeout(() => {
    explorarRelacionesConAnimacion();
  }, 40);
}

function abrirMapaManzanas() {
  cerrarModalExplorarRelaciones();
  setTimeout(() => {
    zoomIntoManzanas();
  }, 40);
}

function abrirMapaPatrimonio() {
  cerrarModalExplorarRelaciones();
  setTimeout(() => {
    zoomIntoPatrimonio();
  }, 40);
}


